window.ETSDATA=window.ETSDATA||{};window.ETSDATA[27]={"lc":{"p1":[{"n":1,"opts":["A woman is closing a door.","A woman is using a shovel.","A woman is pushing a wheelbarrow.","A woman is digging a hole."],"vi":["Một người phụ nữ đang đóng cửa.","Một người phụ nữ đang dùng xẻng.","Một người phụ nữ đang đẩy xe cút kít.","Một người phụ nữ đang đào hố."],"ans":"C","xp":"Tranh: người phụ nữ đẩy xe cút kít đi qua cổng vòm → (C). (A) không đóng cửa, (B)(D) không dùng xẻng hay đào hố (bẫy từ liên quan làm vườn: shovel, dig).","a":"XC-T07-01.mp3","img":"q1.jpg"},{"n":2,"opts":["He is wiping a table.","He is sweeping a yard.","He is arranging potted plants.","He is assembling a chair."],"vi":["Anh ấy đang lau bàn.","Anh ấy đang quét sân.","Anh ấy đang sắp xếp chậu cây.","Anh ấy đang lắp ráp ghế."],"ans":"B","xp":"Tranh: người đàn ông cầm chổi quét sân → (B). (A) không lau bàn, (C) chậu cây có trong tranh nhưng anh không sắp xếp, (D) không lắp ghế.","a":"XC-T07-02.mp3","img":"q2.jpg"},{"n":3,"opts":["A man is resting by a large body of water.","A man is running along a beach.","Some boats are docked at a pier.","An umbrella is casting shade on a beach."],"vi":["Một người đàn ông đang nghỉ ngơi bên mặt nước rộng lớn.","Một người đàn ông đang chạy dọc bãi biển.","Vài chiếc thuyền đang neo ở cầu tàu.","Một chiếc ô đang che bóng trên bãi biển."],"ans":"A","xp":"Tranh: người đàn ông ngồi ghế nghỉ, nhìn ra biển → (A) 'a large body of water' = biển/hồ lớn. (B) không chạy, (C) thuyền ở xa ngoài biển, không neo ở cầu tàu, (D) không có ô.","a":"XC-T07-03.mp3","img":"q3.jpg"},{"n":4,"opts":["A group of people has gathered for a meeting.","One of the women is standing behind a podium.","One of the men is turning on a monitor screen.","A phone is mounted on the wall."],"vi":["Một nhóm người đã tụ họp để họp.","Một trong những người phụ nữ đang đứng sau bục phát biểu.","Một trong những người đàn ông đang bật màn hình.","Một chiếc điện thoại được gắn trên tường."],"ans":"A","xp":"Tranh: nhiều người ngồi quanh bàn, xem tài liệu cùng nhau → đang họp → (A). (B) không có bục, (C) không ai bật màn hình, (D) không có điện thoại trên tường.","a":"XC-T07-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some people are drinking their beverages.","A table is being covered with a cloth.","A man is serving a dish.","A wall is decorated with pictures."],"vi":["Một số người đang uống đồ uống.","Một cái bàn đang được trải khăn.","Một người đàn ông đang phục vụ một món ăn.","Bức tường được trang trí bằng tranh ảnh."],"ans":"D","xp":"Tranh: quán cà phê, trên tường treo nhiều khung tranh → (D). (A) mọi người không đang uống, (B) không ai trải khăn, (C) người đàn ông đứng nói chuyện, không bưng món ăn.","a":"XC-T07-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A train is approaching a station.","Some passengers are checking their luggage.","Some stairs lead down to platforms.","Workers are repairing a railway."],"vi":["Một đoàn tàu đang tiến vào ga.","Một số hành khách đang ký gửi hành lý.","Cầu thang dẫn xuống các sân ga.","Công nhân đang sửa đường ray."],"ans":"C","xp":"Tranh: nhà ga vắng, có cầu thang dẫn xuống sân ga → (C). (A) không thấy tàu, (B)(D) không có người.","a":"XC-T07-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Who was supposed to lock up the store?","qvi":"Ai lẽ ra phải khóa cửa hàng?","opts":["Every night at eleven.","The security manager.","A key to the storage room."],"vi":["Mỗi tối lúc 11 giờ.","Quản lý an ninh.","Chìa khóa phòng kho."],"ans":"B","xp":"Câu hỏi Who → trả lời người: (B) 'Quản lý an ninh'. (A) trả lời When, (C) dùng từ liên tưởng 'key' (lock).","a":"XC-T07-07.mp3"},{"n":8,"q":"Where did you get that sandwich?","qvi":"Bạn mua chiếc bánh mì kẹp đó ở đâu?","opts":["Yes, it's delicious.","At 1 P.M.","From the cafeteria."],"vi":["Vâng, nó ngon lắm.","Lúc 1 giờ chiều.","Ở căng tin."],"ans":"C","xp":"Câu hỏi Where → nơi chốn: (C) 'Ở căng tin'. (A) câu hỏi Wh- không trả lời Yes/No, (B) trả lời When.","a":"XC-T07-08.mp3"},{"n":9,"q":"Why don't you add some visuals to the presentation?","qvi":"Sao bạn không thêm vài hình ảnh minh họa vào bài thuyết trình?","opts":["15 pages long.","Sure, I'll do that now.","No, it's a birthday gift."],"vi":["Dài 15 trang.","Được, tôi sẽ làm ngay.","Không, đó là quà sinh nhật."],"ans":"B","xp":"'Why don't you...?' là lời đề nghị → đồng ý: (B) 'Được, tôi sẽ làm ngay'. (A) liên tưởng presentation – số trang, (C) 'present' (quà) gây nhiễu với presentation.","a":"XC-T07-09.mp3"},{"n":10,"q":"The deliveries were shipped out on time, right?","qvi":"Hàng đã được gửi đi đúng giờ, phải không?","opts":["Yes, the trucks left by 8 A.M.","I want one pint of blueberry.","Free ground shipping."],"vi":["Vâng, xe tải đã đi trước 8 giờ sáng.","Tôi muốn một panh việt quất.","Miễn phí vận chuyển đường bộ."],"ans":"A","xp":"Câu hỏi đuôi xác nhận → (A) 'Vâng, xe tải đã rời đi trước 8 giờ' xác nhận hàng gửi đúng giờ. (C) lặp âm shipped/shipping.","a":"XC-T07-10.mp3"},{"n":11,"q":"When did you check out these materials?","qvi":"Bạn mượn những tài liệu này khi nào?","opts":["Maybe last Wednesday.","At least five business days.","Mark the calendar."],"vi":["Có lẽ là thứ Tư tuần trước.","Ít nhất năm ngày làm việc.","Đánh dấu lịch đi."],"ans":"A","xp":"Câu hỏi When (quá khứ) → mốc thời gian: (A) 'Có lẽ là thứ Tư tuần trước'. (B) trả lời How long, (C) liên tưởng ngày tháng.","a":"XC-T07-11.mp3"},{"n":12,"q":"Won't you attend the reception after the seminar?","qvi":"Bạn không dự tiệc chiêu đãi sau hội thảo à?","opts":["No, I have a prior appointment.","The seminar is very informative.","A visitors' badge."],"vi":["Không, tôi có hẹn trước rồi.","Hội thảo rất bổ ích.","Thẻ khách tham quan."],"ans":"A","xp":"Câu hỏi phủ định Yes/No → (A) 'Không, tôi có hẹn trước' kèm lý do. (B) lặp từ seminar, (C) liên tưởng sự kiện – thẻ khách.","a":"XC-T07-12.mp3"},{"n":13,"q":"Is there any room left in that box?","qvi":"Trong thùng đó còn chỗ trống không?","opts":["Yes, we should use an express service.","At the Homer's Hotel.","No, it's completely full."],"vi":["Có, chúng ta nên dùng dịch vụ chuyển phát nhanh.","Ở khách sạn Homer.","Không, nó đầy hoàn toàn rồi."],"ans":"C","xp":"'room' ở đây = chỗ trống → (C) 'Không, nó đầy rồi'. (B) hiểu nhầm room = phòng khách sạn, (A) trả lời Yes nhưng nội dung không liên quan.","a":"XC-T07-13.mp3"},{"n":14,"q":"Are you fluent in Spanish or German?","qvi":"Bạn thông thạo tiếng Tây Ban Nha hay tiếng Đức?","opts":["Attention passengers to Barcelona.","Both, actually.","They are made in German."],"vi":["Hành khách đi Barcelona chú ý.","Thật ra là cả hai.","Chúng được sản xuất bằng tiếng Đức."],"ans":"B","xp":"Câu hỏi lựa chọn A or B → (B) 'Thật ra là cả hai'. (A) liên tưởng Tây Ban Nha – Barcelona, (C) lặp từ German.","a":"XC-T07-14.mp3"},{"n":15,"q":"When does your business trip start?","qvi":"Chuyến công tác của bạn bắt đầu khi nào?","opts":["In Los Angeles.","Boarding pass and passport.","My flight leaves on Sunday."],"vi":["Ở Los Angeles.","Thẻ lên máy bay và hộ chiếu.","Chuyến bay của tôi cất cánh vào Chủ Nhật."],"ans":"C","xp":"Câu hỏi When → (C) 'Chuyến bay cất cánh Chủ Nhật' = chuyến đi bắt đầu Chủ Nhật. (A) trả lời Where, (B) liên tưởng chuyến đi.","a":"XC-T07-15.mp3"},{"n":16,"q":"Weren't there more crates on the loading dock?","qvi":"Không phải ở bến bốc hàng còn nhiều thùng hơn sao?","opts":["Please place the supply order today.","Michelle moved them to the stockroom.","An extra delivery truck."],"vi":["Vui lòng đặt hàng vật tư hôm nay.","Michelle đã chuyển chúng vào kho rồi.","Thêm một xe tải giao hàng."],"ans":"B","xp":"Hỏi vì sao thùng hàng ít đi → (B) 'Michelle đã chuyển chúng vào kho' giải thích. (A)(C) liên tưởng bốc dỡ hàng.","a":"XC-T07-16.mp3"},{"n":17,"q":"How do I request reimbursement for work expenses?","qvi":"Làm sao để tôi xin hoàn tiền chi phí công tác?","opts":["Consult the employee handbook.","It's too expensive.","On the first of each month."],"vi":["Hãy xem sổ tay nhân viên.","Nó quá đắt.","Vào ngày mùng 1 mỗi tháng."],"ans":"A","xp":"Câu hỏi How (cách làm) → (A) 'Hãy tham khảo sổ tay nhân viên'. (B) lặp âm expenses/expensive, (C) trả lời When.","a":"XC-T07-17.mp3"},{"n":18,"q":"Do you want cheesecake for your dessert?","qvi":"Bạn có muốn ăn bánh phô mai tráng miệng không?","opts":["A customized birthday cake.","What else do you have on the menu?","Sorry, this is the last piece."],"vi":["Một chiếc bánh sinh nhật đặt riêng.","Thực đơn còn món gì khác không?","Xin lỗi, đây là miếng cuối cùng."],"ans":"B","xp":"Đáp gián tiếp bằng câu hỏi lại: (B) 'Thực đơn còn món nào khác?' (ý chưa muốn bánh phô mai). (A) lặp từ cake, (C) là lời của người bán chứ không phải người được mời.","a":"XC-T07-18.mp3"},{"n":19,"q":"You can't issue me a full refund, can you?","qvi":"Bạn không thể hoàn tiền toàn bộ cho tôi, phải không?","opts":["No, but we can give you store credit.","It's the July issue.","That's a reasonable price."],"vi":["Không, nhưng chúng tôi có thể cho bạn tín dụng mua hàng tại cửa hàng.","Đó là số báo tháng 7.","Đó là giá hợp lý."],"ans":"A","xp":"Câu hỏi đuôi → (A) 'Không, nhưng có thể cho tín dụng mua hàng' – trả lời và đưa phương án khác. (B) lặp từ issue (số báo).","a":"XC-T07-19.mp3"},{"n":20,"q":"How do I edit this video?","qvi":"Làm sao để chỉnh sửa video này?","opts":["Jonathan might know.","I haven't seen it yet.","Yes, follow the sign."],"vi":["Có lẽ Jonathan biết.","Tôi chưa xem nó.","Vâng, hãy đi theo biển chỉ dẫn."],"ans":"A","xp":"Câu trả lời gián tiếp 'Tôi không biết, hỏi người khác': (A) 'Có lẽ Jonathan biết'. (C) câu hỏi How không trả lời Yes, (B) liên tưởng video.","a":"XC-T07-20.mp3"},{"n":21,"q":"I reserved this meeting room from 2:00 P.M.","qvi":"Tôi đã đặt phòng họp này từ 2 giờ chiều.","opts":["A screen and beam projector.","It has a larger space.","We're about to leave."],"vi":["Màn chiếu và máy chiếu.","Nó có không gian rộng hơn.","Chúng tôi sắp đi rồi."],"ans":"C","xp":"Câu trần thuật nhắc khéo nhóm kia trả phòng → (C) 'Chúng tôi sắp đi rồi'. (A)(B) liên tưởng phòng họp.","a":"XC-T07-21.mp3"},{"n":22,"q":"Why is the office so cold today?","qvi":"Sao hôm nay văn phòng lạnh thế?","opts":["Tomorrow morning.","Here is a remote climate controller.","You can order a hot one instead."],"vi":["Sáng mai.","Đây là điều khiển điều hòa từ xa.","Bạn có thể gọi đồ nóng thay thế."],"ans":"B","xp":"Than lạnh → đưa giải pháp: (B) 'Đây là điều khiển điều hòa' để chỉnh nhiệt độ. (A) trả lời When, (C) lạnh – nóng là liên tưởng đồ uống.","a":"XC-T07-22.mp3"},{"n":23,"q":"You forgot to include your diploma with your application.","qvi":"Bạn quên nộp kèm bằng tốt nghiệp trong hồ sơ.","opts":["Since I graduated.","I'll send you a copy right away.","The discount was already applied."],"vi":["Kể từ khi tôi tốt nghiệp.","Tôi sẽ gửi bản sao cho bạn ngay.","Giảm giá đã được áp dụng rồi."],"ans":"B","xp":"Bị nhắc thiếu giấy tờ → khắc phục: (B) 'Tôi sẽ gửi bản sao ngay'. (A) liên tưởng diploma – graduated, (C) lặp âm application/applied.","a":"XC-T07-23.mp3"},{"n":24,"q":"What was covered in the weekly meeting?","qvi":"Cuộc họp hằng tuần đã bàn những gì?","opts":["I took a day off yesterday.","Summarize your plan.","The cover has a new design."],"vi":["Hôm qua tôi nghỉ phép.","Hãy tóm tắt kế hoạch của bạn.","Bìa có thiết kế mới."],"ans":"A","xp":"Trả lời gián tiếp 'tôi không biết vì vắng mặt': (A) 'Hôm qua tôi nghỉ'. (C) lặp âm covered/cover, (B) không hợp.","a":"XC-T07-24.mp3"},{"n":25,"q":"When are we going to receive the year-end bonus?","qvi":"Khi nào chúng ta nhận thưởng cuối năm?","opts":["It hasn't been announced.","$500 for each.","I need your signature here."],"vi":["Vẫn chưa được thông báo.","Mỗi người 500 đô la.","Tôi cần chữ ký của bạn ở đây."],"ans":"A","xp":"Câu hỏi When → trả lời 'chưa biết': (A) 'Vẫn chưa được thông báo'. (B) trả lời How much, (C) liên tưởng nhận tiền – ký nhận.","a":"XC-T07-25.mp3"},{"n":26,"q":"Is there a private room for six people at your restaurant?","qvi":"Nhà hàng có phòng riêng cho sáu người không?","opts":["We are open until 10 P.M. on weekdays.","They are all fully booked.","How would you like your steak?"],"vi":["Ngày thường chúng tôi mở cửa đến 10 giờ tối.","Các phòng đều kín chỗ rồi.","Quý khách muốn món bít tết thế nào?"],"ans":"B","xp":"Hỏi có phòng riêng không → (B) 'Các phòng đều kín chỗ' (= không còn). (A)(C) liên tưởng nhà hàng.","a":"XC-T07-26.mp3"},{"n":27,"q":"The meeting was rescheduled to tomorrow morning.","qvi":"Cuộc họp đã được dời sang sáng mai.","opts":["Enough copies for the participants.","No one told me about that.","I haven't met him either."],"vi":["Đủ bản in cho người tham dự.","Không ai báo tôi chuyện đó cả.","Tôi cũng chưa gặp anh ấy."],"ans":"B","xp":"Phản hồi tin dời lịch → (B) 'Không ai báo tôi cả'. (A) liên tưởng cuộc họp, (C) lặp âm meeting/met.","a":"XC-T07-27.mp3"},{"n":28,"q":"What did you think about the last candidate you interviewed?","qvi":"Bạn nghĩ sao về ứng viên cuối cùng bạn phỏng vấn?","opts":["It won't last that long.","No, I can't do that for you.","I wish she would start soon."],"vi":["Nó sẽ không kéo dài lâu vậy đâu.","Không, tôi không làm điều đó cho bạn được.","Tôi mong cô ấy sớm bắt đầu đi làm."],"ans":"C","xp":"Hỏi ý kiến về ứng viên → (C) 'Mong cô ấy sớm bắt đầu làm' = đánh giá tốt. (A) lặp từ last, (B) câu hỏi Wh- không trả lời No.","a":"XC-T07-28.mp3"},{"n":29,"q":"Why was the floor plan for the new store not approved?","qvi":"Sao bản vẽ mặt bằng cửa hàng mới không được duyệt?","opts":["I put it in the display window.","The store is under renovation now.","You didn't check the e-mail from the contractor?"],"vi":["Tôi đặt nó ở tủ kính trưng bày.","Cửa hàng đang được sửa chữa.","Bạn chưa xem e-mail của nhà thầu à?"],"ans":"C","xp":"Câu hỏi Why → trả lời gián tiếp: (C) 'Bạn chưa xem e-mail của nhà thầu à?' (lý do có trong e-mail). (A)(B) liên tưởng cửa hàng.","a":"XC-T07-29.mp3"},{"n":30,"q":"Is our network back online now?","qvi":"Mạng của chúng ta đã hoạt động lại chưa?","opts":["I think so, but very slow.","I already have a computer.","On our homepage."],"vi":["Tôi nghĩ là rồi, nhưng rất chậm.","Tôi có máy tính rồi.","Trên trang chủ của chúng ta."],"ans":"A","xp":"Câu hỏi Yes/No → (A) 'Tôi nghĩ là rồi, nhưng rất chậm'. (B)(C) liên tưởng máy tính, mạng.","a":"XC-T07-30.mp3"},{"n":31,"q":"I'm going to send this signed contract to our client.","qvi":"Tôi định gửi bản hợp đồng đã ký này cho khách hàng.","opts":["At the bottom of the last page.","It will automatically be renewed.","I could bring it there myself."],"vi":["Ở cuối trang cuối.","Nó sẽ được tự động gia hạn.","Tôi có thể tự mang đến đó."],"ans":"C","xp":"Phản hồi đề xuất → (C) 'Tôi có thể tự mang đến đó' (đề nghị cách khác). (A)(B) liên tưởng hợp đồng (chỗ ký, gia hạn).","a":"XC-T07-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Excuse me, Mr. Calderon. I've been having some trouble with the new accounting software. It's quite different from the previous one that I was familiar with. I attended a training course last week, but I'm still getting used to it. I keep referring to this user guide I received during the training.","Xin lỗi, anh Calderon. Tôi đang gặp khó khăn với phần mềm kế toán mới. Nó khác hẳn phần mềm cũ mà tôi quen dùng. Tuần trước tôi đã dự khóa đào tạo nhưng vẫn đang làm quen. Tôi cứ phải xem cuốn hướng dẫn sử dụng được phát trong khóa học."],["W","That must be the problem. I wasn't in the office last week, so I missed the training. Would you mind if I borrow yours? I will get it back to you as soon as I make a photocopy of it.","Chắc đó là vấn đề rồi. Tuần trước tôi không có ở văn phòng nên đã bỏ lỡ khóa đào tạo. Anh cho tôi mượn cuốn của anh được không? Tôi sẽ trả ngay sau khi photo xong."],["M","That's a waste of time. It's more than 200 pages. Why not go ask the IT department? I'm sure they have extra copies in their office.","Như vậy mất thời gian lắm. Nó dày hơn 200 trang. Sao chị không hỏi phòng IT? Tôi chắc họ có bản dư trong văn phòng."]],"qs":[{"n":32,"q":"What is the main topic of the conversation?","qvi":"Chủ đề chính của cuộc hội thoại là gì?","opts":["Computer software","A project budget","A training session","A department transfer"],"vi":["Phần mềm máy tính","Ngân sách dự án","Buổi đào tạo","Việc chuyển phòng ban"],"ans":"A","xp":"Câu đầu: 'I've been having some trouble with the new accounting software' và cả bài nói về phần mềm mới → (A)."},{"n":33,"q":"What does the woman ask for?","qvi":"Người phụ nữ xin cái gì?","opts":["Office supplies","A job description","A user's manual","A request form"],"vi":["Đồ dùng văn phòng","Bản mô tả công việc","Sách hướng dẫn sử dụng","Mẫu đơn yêu cầu"],"ans":"C","xp":"Người đàn ông nhắc 'this user guide', người phụ nữ hỏi 'Would you mind if I borrow yours?' → mượn sách hướng dẫn → (C). user guide = user's manual."},{"n":34,"q":"What is the woman asked to do?","qvi":"Người phụ nữ được đề nghị làm gì?","opts":["Submit original receipts","Contact a moving company","Complete a survey","Visit another department"],"vi":["Nộp hóa đơn gốc","Liên hệ công ty chuyển nhà","Làm khảo sát","Đến phòng ban khác"],"ans":"D","xp":"Người đàn ông: 'Why not go ask the IT department?' → đến hỏi phòng IT → (D)."}],"a":"XC-T07-32-34.mp3"},{"ns":[35,37],"script":[["W","Mr. Brunswick, what do you think of this floor plan for our museum's upcoming special exhibit?","Anh Brunswick, anh thấy sơ đồ bố trí cho triển lãm đặc biệt sắp tới của bảo tàng thế nào?"],["M","It looks like it would be fine for a normal exhibit, but perhaps we should create more floor space. How many guests have reserved tickets so far?","Có vẻ ổn với một triển lãm bình thường, nhưng có lẽ chúng ta nên tạo thêm không gian. Đến giờ đã có bao nhiêu khách đặt vé rồi?"],["W","We've almost sold out for the opening night. We should have a lot more visitors than any normal day.","Đêm khai mạc gần như bán hết vé rồi. Chắc chắn sẽ đông khách hơn nhiều so với ngày thường."],["M","In that case, I think we should move more of the artwork against the walls to make more room for people to walk through the middle.","Vậy thì tôi nghĩ chúng ta nên dời thêm tác phẩm sát vào tường để có thêm chỗ cho mọi người đi lại ở giữa."]],"qs":[{"n":35,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["An artist","A college professor","A curator","A security guard"],"vi":["Họa sĩ","Giáo sư đại học","Người phụ trách bảo tàng/triển lãm","Nhân viên bảo vệ"],"ans":"C","xp":"Hai người bàn 'floor plan for our museum's upcoming special exhibit' và cách bố trí tác phẩm → người phụ trách triển lãm (curator) → (C)."},{"n":36,"q":"What does the man ask about?","qvi":"Người đàn ông hỏi về điều gì?","opts":["The expected number of guests","Upcoming event schedules","Ticket prices","Interview questions"],"vi":["Số khách dự kiến","Lịch sự kiện sắp tới","Giá vé","Câu hỏi phỏng vấn"],"ans":"A","xp":"'How many guests have reserved tickets so far?' → hỏi số khách dự kiến → (A)."},{"n":37,"q":"What does the man suggest?","qvi":"Người đàn ông đề xuất gì?","opts":["Rearranging some artwork","Making a stage at the front","Ordering more food","Confirming the guest list"],"vi":["Sắp xếp lại một số tác phẩm","Dựng sân khấu phía trước","Đặt thêm đồ ăn","Xác nhận danh sách khách"],"ans":"A","xp":"'we should move more of the artwork against the walls' → sắp xếp lại tác phẩm → (A)."}],"a":"XC-T07-35-37.mp3"},{"ns":[38,40],"script":[["M","Caitlyn, do you have a minute? I saw the memo about the company-wide training session scheduled for Monday. Most of my team members are going to Paris to attend a trade fair next week.","Caitlyn, chị có rảnh một phút không? Tôi thấy bản thông báo về buổi đào tạo toàn công ty vào thứ Hai. Phần lớn thành viên nhóm tôi sẽ sang Paris dự hội chợ thương mại tuần tới."],["W","Really? Well, everyone is supposed to get the safety certification from the training. When will they come back?","Thật sao? Mọi người đều phải lấy chứng nhận an toàn từ buổi đào tạo đó. Khi nào họ về?"],["M","They will be out for the whole week. Umm... as always, if the session is offered online, they can access it from the hotel and complete the training. Can you e-mail me a link for it?","Họ đi cả tuần. Ừm... như mọi khi, nếu buổi học có trực tuyến thì họ có thể vào học từ khách sạn và hoàn thành khóa đào tạo. Chị gửi tôi đường link qua e-mail được không?"],["W","Unfortunately, not this time. All employees will take a test for the safety certification after the session. I don't have any authority to make an exception for them. I suppose we don't have any other choice. I'll arrange another session sometime next month.","Tiếc là lần này thì không. Tất cả nhân viên sẽ làm bài kiểm tra lấy chứng nhận an toàn sau buổi học. Tôi không có quyền ngoại lệ cho họ. Chắc là không còn cách nào khác. Tôi sẽ sắp xếp một buổi khác vào tháng sau."]],"qs":[{"n":38,"q":"What caused the problem?","qvi":"Điều gì gây ra vấn đề?","opts":["New employees are inexperienced.","A conference room was double-booked.","Some employees will be out of the office.","Training materials were not printed."],"vi":["Nhân viên mới thiếu kinh nghiệm.","Phòng họp bị đặt trùng.","Một số nhân viên sẽ vắng mặt ở văn phòng.","Tài liệu đào tạo chưa được in."],"ans":"C","xp":"'Most of my team members are going to Paris to attend a trade fair next week' → một số nhân viên đi vắng → (C)."},{"n":39,"q":"What does the man ask about?","qvi":"Người đàn ông hỏi về điều gì?","opts":["Taking an extended vacation","Requesting a tuition reimbursement","Getting training online","Booking an earlier flight"],"vi":["Nghỉ phép dài ngày","Xin hoàn học phí","Học đào tạo trực tuyến","Đặt chuyến bay sớm hơn"],"ans":"C","xp":"'if the session is offered online, they can access it from the hotel... Can you e-mail me a link for it?' → hỏi về học trực tuyến → (C)."},{"n":40,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Hold another session","E-mail materials","Excuse an absence","Postpone a test"],"vi":["Tổ chức thêm một buổi","Gửi tài liệu qua e-mail","Miễn cho việc vắng mặt","Hoãn bài kiểm tra"],"ans":"A","xp":"'I'll arrange another session sometime next month' → tổ chức buổi khác → (A). arrange = hold."}],"a":"XC-T07-38-40.mp3"},{"ns":[41,43],"script":[["M","Here's your new phone, Ms. Wheeler. Shall I transfer all the data and contacts from your old phone?","Đây là điện thoại mới của chị, chị Wheeler. Tôi chuyển toàn bộ dữ liệu và danh bạ từ điện thoại cũ sang nhé?"],["W1","No, that's alright. I can do that at any time, can't I?","Không cần đâu. Tôi có thể tự làm bất cứ lúc nào, phải không?"],["M","Of course you can, even by yourself. Also, if you have this software installed on your computer, you can transfer any data from your phone to your devices and vice versa.","Tất nhiên rồi, chị tự làm cũng được. Ngoài ra, nếu chị cài phần mềm này trên máy tính, chị có thể chuyển mọi dữ liệu từ điện thoại sang các thiết bị khác và ngược lại."],["W1","That sounds convenient. How can I do that?","Nghe tiện quá. Làm thế nào vậy?"],["M","Jodi will assist you with that. Jodi, would you give her a hand with the data transfer?","Jodi sẽ hỗ trợ chị. Jodi, em giúp chị ấy chuyển dữ liệu nhé?"],["W2","Sure, no problem. Ms. Wheeler, I can show you step by step on this computer.","Vâng, không vấn đề gì. Chị Wheeler, em có thể chỉ chị từng bước trên máy tính này."],["W1","Oh... sorry. I'm actually running a little late.","Ồ... xin lỗi. Thật ra tôi đang hơi trễ giờ."],["W2","Okay, then here is a CD and a manual. It explains how to get started.","Vậy thì đây là đĩa CD và sách hướng dẫn. Trong đó giải thích cách bắt đầu."]],"qs":[{"n":41,"q":"Where is the conversation most likely taking place?","qvi":"Cuộc hội thoại nhiều khả năng diễn ra ở đâu?","opts":["At a manufacturing plant","At an electronics store","At a tourist information booth","At a medical clinic"],"vi":["Ở nhà máy sản xuất","Ở cửa hàng điện tử","Ở quầy thông tin du lịch","Ở phòng khám"],"ans":"B","xp":"'Here's your new phone... Shall I transfer all the data' → bán và hỗ trợ điện thoại → cửa hàng điện tử → (B)."},{"n":42,"q":"According to the man, why should Ms. Wheeler install software?","qvi":"Theo người đàn ông, vì sao chị Wheeler nên cài phần mềm?","opts":["To pay a monthly bill","To download coupons for local attractions","To move files to a new device","To update her old computer"],"vi":["Để thanh toán hóa đơn tháng","Để tải phiếu giảm giá điểm tham quan","Để chuyển tệp sang thiết bị mới","Để cập nhật máy tính cũ"],"ans":"C","xp":"'if you have this software installed... you can transfer any data from your phone to your devices' → chuyển dữ liệu sang thiết bị → (C)."},{"n":43,"q":"What does Jodi give to Ms. Wheeler?","qvi":"Jodi đưa gì cho chị Wheeler?","opts":["A booklet","A business card","A warranty","A membership form"],"vi":["Một cuốn sách nhỏ","Danh thiếp","Phiếu bảo hành","Mẫu đăng ký hội viên"],"ans":"A","xp":"Jodi: 'here is a CD and a manual' → sách hướng dẫn = booklet → (A)."}],"a":"XC-T07-41-43.mp3"},{"ns":[44,46],"script":[["M","Brenda, you know that Green Hill Construction buys building materials from our store instead of their supplier when they need something quickly, right? Well, I'm wondering if we should start offering them a discount.","Brenda, chị biết Green Hill Construction mua vật liệu xây dựng ở cửa hàng mình thay vì nhà cung cấp của họ khi cần gấp, đúng không? Tôi đang nghĩ có nên bắt đầu giảm giá cho họ không."],["W","It didn't seem worth it to create a special contract when we looked into it last year.","Năm ngoái khi xem xét, mình thấy lập hợp đồng riêng có vẻ không đáng."],["M","Yes, but they're providing more business than ever before. We should reward them for their loyalty.","Đúng, nhưng giờ họ mua của mình nhiều hơn bao giờ hết. Mình nên tri ân sự gắn bó của họ."],["W","I see what you mean.","Tôi hiểu ý anh."],["M","Let's look at what the company has bought over the past six months to see if we can come up with a fair rate.","Hãy xem công ty đó đã mua những gì trong sáu tháng qua để đưa ra mức giá hợp lý."]],"qs":[{"n":44,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a construction company","At an energy supplier","At an interior design firm","At a hardware store"],"vi":["Ở công ty xây dựng","Ở công ty cung cấp năng lượng","Ở công ty thiết kế nội thất","Ở cửa hàng vật liệu, dụng cụ"],"ans":"D","xp":"'Green Hill Construction buys building materials from our store' → họ làm ở cửa hàng bán vật liệu (hardware store) → (D). (A) là khách hàng của họ."},{"n":45,"q":"What does the man suggest when he says, \"but they're providing more business than ever before\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"nhưng giờ họ mua của mình nhiều hơn bao giờ hết\"?","opts":["A competitor's market share is growing.","A client deserves a special contract.","A loyalty program is becoming too expensive.","A discount is no longer necessary."],"vi":["Thị phần đối thủ đang tăng.","Một khách hàng xứng đáng có hợp đồng riêng.","Chương trình khách hàng thân thiết đang quá tốn kém.","Không cần giảm giá nữa."],"ans":"B","xp":"Người phụ nữ nói năm ngoái thấy hợp đồng riêng không đáng; người đàn ông phản bác 'but they're providing more business than ever before. We should reward them' → khách hàng này xứng đáng có hợp đồng ưu đãi → (B)."},{"n":46,"q":"What does the man suggest doing?","qvi":"Người đàn ông đề xuất làm gì?","opts":["Using a trial service","Sending out some samples","Reviewing purchasing history","Checking an exchange rate"],"vi":["Dùng thử dịch vụ","Gửi hàng mẫu","Xem lại lịch sử mua hàng","Kiểm tra tỷ giá"],"ans":"C","xp":"'Let's look at what the company has bought over the past six months' → xem lại lịch sử mua hàng → (C)."}],"a":"XC-T07-44-46.mp3"},{"ns":[47,49],"script":[["M","Rosa, I just got a call from Tyler's Toys. They need a staff lunch for 50 servings for their event tomorrow instead of 20.","Rosa, tôi vừa nhận cuộc gọi từ Tyler's Toys. Họ cần bữa trưa cho 50 suất cho sự kiện ngày mai thay vì 20."],["W","That's more than double. Do they want the same three-course meal?","Vậy là hơn gấp đôi. Họ vẫn muốn suất ăn ba món như cũ à?"],["M","No, they changed it to a buffet-style lunch.","Không, họ đổi sang bữa trưa kiểu buffet."],["W","If so, that's too much for me to handle by lunchtime tomorrow.","Nếu vậy thì quá sức tôi để kịp trước trưa mai."],["M","Steve was supposed to have off tomorrow, but I could call him in to help you. Also, I'll hire a part-time assistant to clean and prepare ingredients.","Steve lẽ ra được nghỉ ngày mai, nhưng tôi có thể gọi cậu ấy đến giúp chị. Ngoài ra tôi sẽ thuê một trợ lý bán thời gian để rửa và sơ chế nguyên liệu."],["W","Okay, I should be able to do it with their help.","Được, có họ giúp thì tôi làm được."]],"qs":[{"n":47,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a toy store","At a catering company","At a supermarket","At a real estate agency"],"vi":["Ở cửa hàng đồ chơi","Ở công ty cung cấp suất ăn","Ở siêu thị","Ở công ty bất động sản"],"ans":"B","xp":"Khách (Tyler's Toys) đặt 50 suất ăn trưa, đổi từ 'three-course meal' sang 'buffet-style lunch' → công ty phục vụ ăn uống → (B). (A) Tyler's Toys là khách hàng."},{"n":48,"q":"What problem does the woman mention?","qvi":"Người phụ nữ nêu vấn đề gì?","opts":["The workload is too heavy.","A machine is malfunctioning.","The room is not spacious enough.","The price of materials is increasing."],"vi":["Khối lượng công việc quá nặng.","Một máy bị trục trặc.","Phòng không đủ rộng.","Giá nguyên liệu tăng."],"ans":"A","xp":"'that's too much for me to handle by lunchtime tomorrow' → việc quá nhiều → (A)."},{"n":49,"q":"What will the speakers do to resolve the problem?","qvi":"Họ sẽ giải quyết vấn đề thế nào?","opts":["Place a bulk order","Delay an event","Look for different vendors","Ask for a colleague's help"],"vi":["Đặt hàng số lượng lớn","Hoãn sự kiện","Tìm nhà cung cấp khác","Nhờ đồng nghiệp giúp"],"ans":"D","xp":"'Steve was supposed to have off tomorrow, but I could call him in to help you' → nhờ đồng nghiệp giúp → (D)."}],"a":"XC-T07-47-49.mp3"},{"ns":[50,52],"script":[["M1","Excuse me. We're wondering if this hotel has an on-site restaurant.","Xin lỗi. Chúng tôi muốn hỏi khách sạn có nhà hàng trong khuôn viên không."],["W","I'm sorry. We don't have a place to eat here in the building, but there are a number of restaurants nearby.","Rất tiếc. Trong tòa nhà không có chỗ ăn, nhưng gần đây có nhiều nhà hàng."],["M1","Oh, um... well, I'm not sure we'd be comfortable walking around a lot. We're not familiar with this neighborhood.","Ồ, ừm... chúng tôi không chắc mình thấy thoải mái khi đi lại nhiều. Chúng tôi không quen khu này."],["M2","Yeah. We've never stayed in this area before.","Đúng vậy. Chúng tôi chưa từng ở khu này."],["W","I completely understand. Then I'd recommend the Bohemian Café.","Tôi hoàn toàn hiểu. Vậy tôi giới thiệu quán Bohemian Café."],["M1","Is it far from here?","Có xa đây không?"],["W","Not at all. It's right across the street. And I'd be happy to call and reserve a table for you.","Không hề. Nó ngay bên kia đường. Và tôi rất sẵn lòng gọi đặt bàn giúp hai anh."]],"qs":[{"n":50,"q":"Where does the woman work?","qvi":"Người phụ nữ làm việc ở đâu?","opts":["At a restaurant","At a theater","At a hotel","At a clothing shop"],"vi":["Ở nhà hàng","Ở nhà hát","Ở khách sạn","Ở cửa hàng quần áo"],"ans":"C","xp":"Khách hỏi 'if this hotel has an on-site restaurant', cô trả lời 'We don't have a place to eat here in the building' → cô làm ở khách sạn → (C)."},{"n":51,"q":"Why are the men concerned?","qvi":"Vì sao hai người đàn ông lo lắng?","opts":["They have a limited amount of time.","They do not know the area well.","They have a small budget.","They were given the wrong item."],"vi":["Họ có ít thời gian.","Họ không rành khu vực này.","Họ có ít tiền.","Họ bị đưa nhầm đồ."],"ans":"B","xp":"'We're not familiar with this neighborhood' / 'We've never stayed in this area before' → không rành khu vực → (B)."},{"n":52,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Provide a refund","Make a reservation","Print out a map","Issue a receipt"],"vi":["Hoàn tiền","Đặt chỗ","In bản đồ","Xuất hóa đơn"],"ans":"B","xp":"'I'd be happy to call and reserve a table for you' → đặt bàn → (B)."}],"a":"XC-T07-50-52.mp3"},{"ns":[53,55],"script":[["M","Good morning, Ms. Hummell. It's a pleasure to meet a representative of Cedarburg University.","Chào buổi sáng, bà Hummell. Rất vui được gặp đại diện của Đại học Cedarburg."],["W","You may have heard from the media that the National College Athletes Association requires us to upgrade our sports facilities, including the main stadium and indoor sports arena.","Có lẽ ông đã nghe trên báo đài rằng Hiệp hội Vận động viên Đại học Quốc gia yêu cầu chúng tôi nâng cấp cơ sở thể thao, gồm sân vận động chính và nhà thi đấu trong nhà."],["M","Is there anything in particular that you have in mind?","Bà có ý tưởng cụ thể nào không?"],["W","First, we want to increase the seating capacity of the main stadium up to 30,000 and replace the seats with more comfortable ones.","Trước hết, chúng tôi muốn tăng sức chứa sân vận động chính lên 30.000 chỗ và thay ghế bằng loại thoải mái hơn."],["M","You've come to the right place, then. We manufacture and install a wide variety of stadium seats made of diverse materials. In addition, for nominal fees, we offer seasonal plans that include visits to maintain seats after every game.","Vậy bà đã đến đúng chỗ rồi. Chúng tôi sản xuất và lắp đặt nhiều loại ghế sân vận động bằng nhiều chất liệu. Ngoài ra, với mức phí nhỏ, chúng tôi có gói theo mùa gồm việc đến bảo dưỡng ghế sau mỗi trận đấu."]],"qs":[{"n":53,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["An architect","A journalist","A university official","An athlete"],"vi":["Kiến trúc sư","Nhà báo","Cán bộ trường đại học","Vận động viên"],"ans":"C","xp":"'It's a pleasure to meet a representative of Cedarburg University' → bà là đại diện của trường đại học → (C)."},{"n":54,"q":"What are the speakers discussing?","qvi":"Họ đang bàn về điều gì?","opts":["Financial aid","A game schedule","Tree planting","Facility upgrades"],"vi":["Hỗ trợ tài chính","Lịch thi đấu","Trồng cây","Nâng cấp cơ sở vật chất"],"ans":"D","xp":"'requires us to upgrade our sports facilities' + tăng chỗ ngồi, thay ghế → nâng cấp cơ sở vật chất → (D)."},{"n":55,"q":"What does the man say his company offers for small fees?","qvi":"Người đàn ông nói công ty ông cung cấp gì với phí nhỏ?","opts":["Regular software updates","A seasonal maintenance plan","An insurance plan","Security patrols"],"vi":["Cập nhật phần mềm định kỳ","Gói bảo dưỡng theo mùa","Gói bảo hiểm","Tuần tra an ninh"],"ans":"B","xp":"'for nominal fees, we offer seasonal plans that include visits to maintain seats' → gói bảo dưỡng theo mùa → (B). nominal fees = small fees."}],"a":"XC-T07-53-55.mp3"},{"ns":[56,58],"script":[["W","Sandeep, are you busy right now? I've just finished writing the information sheet that I'll give to the Attica Sales representatives during my presentation. Could you check it and give me some tips?","Sandeep, anh có bận không? Tôi vừa viết xong tờ thông tin sẽ phát cho đại diện của Attica Sales trong buổi thuyết trình. Anh xem giúp và góp ý cho tôi được không?"],["M","Sure, but it would be better to ask someone more familiar with the company. Actually, Ms. Kojima used to work at Attica Sales.","Được, nhưng tốt hơn là hỏi người hiểu rõ công ty đó. Thật ra, chị Kojima từng làm ở Attica Sales."],["W","I didn't know that. I'll talk to her right now. I know we're not the only company that Attica Sales is thinking about hiring. We need to find a way to make our company stand out from the rest.","Tôi không biết điều đó. Tôi sẽ nói chuyện với chị ấy ngay. Tôi biết chúng ta không phải công ty duy nhất mà Attica Sales đang cân nhắc thuê. Chúng ta cần tìm cách làm công ty mình nổi bật hơn các bên khác."]],"qs":[{"n":56,"q":"What does the woman say she has done?","qvi":"Người phụ nữ nói cô đã làm gì?","opts":["Written a handout","Found some incorrect information","Visited the Attica Sales office","Rescheduled a presentation"],"vi":["Viết tài liệu phát tay","Phát hiện thông tin sai","Đến văn phòng Attica Sales","Dời lịch thuyết trình"],"ans":"A","xp":"'I've just finished writing the information sheet that I'll give to the Attica Sales representatives' → tài liệu phát tay → (A)."},{"n":57,"q":"What does the man suggest when he says, \"Ms. Kojima used to work at Attica Sales\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"chị Kojima từng làm ở Attica Sales\"?","opts":["Ms. Kojima is a strong job candidate.","Ms. Kojima will introduce a new client.","Ms. Kojima can give the woman some advice.","Ms. Kojima should be in charge of a project."],"vi":["Chị Kojima là ứng viên mạnh.","Chị Kojima sẽ giới thiệu khách mới.","Chị Kojima có thể góp ý cho người phụ nữ.","Chị Kojima nên phụ trách dự án."],"ans":"C","xp":"Trước đó ông nói 'it would be better to ask someone more familiar with the company' → chị Kojima hiểu công ty đó, có thể góp ý → (C)."},{"n":58,"q":"According to the woman, what are the Attica Sales representatives doing?","qvi":"Theo người phụ nữ, đại diện Attica Sales đang làm gì?","opts":["Increasing their advertising","Expanding their business overseas","Considering several companies","Retraining their employees"],"vi":["Tăng quảng cáo","Mở rộng kinh doanh ra nước ngoài","Cân nhắc nhiều công ty","Đào tạo lại nhân viên"],"ans":"C","xp":"'we're not the only company that Attica Sales is thinking about hiring' → họ đang cân nhắc nhiều công ty → (C)."}],"a":"XC-T07-56-58.mp3"},{"ns":[59,61],"script":[["M","Thanks for allowing me to interview you. My professor will be really impressed if I include a quote from you when I give my presentation about your airline.","Cảm ơn bà đã cho tôi phỏng vấn. Giáo sư của tôi sẽ rất ấn tượng nếu tôi trích lời bà khi thuyết trình về hãng hàng không của bà."],["W","I'm glad to hear that. I founded Atlantic Airlines with a goal of utmost customer satisfaction. We always do our best to achieve it.","Rất vui khi nghe vậy. Tôi sáng lập Atlantic Airlines với mục tiêu làm khách hàng hài lòng tuyệt đối. Chúng tôi luôn cố gắng hết sức để đạt được điều đó."],["M","That's interesting. What do you plan to do to increase your customer satisfaction?","Thú vị quá. Bà dự định làm gì để tăng sự hài lòng của khách hàng?"],["W","We will introduce a new fare class, Premium Economy. We are removing some seats to provide more legroom for our customers before the summer peak travel time.","Chúng tôi sẽ ra mắt hạng vé mới, Phổ thông đặc biệt. Chúng tôi đang bỏ bớt một số ghế để khách có thêm chỗ để chân trước mùa du lịch cao điểm mùa hè."]],"qs":[{"n":59,"q":"Who most likely is the woman?","qvi":"Người phụ nữ nhiều khả năng là ai?","opts":["A sales manager","An engineer","An author","A business owner"],"vi":["Quản lý bán hàng","Kỹ sư","Tác giả","Chủ doanh nghiệp"],"ans":"D","xp":"'I founded Atlantic Airlines' → bà là người sáng lập, chủ doanh nghiệp → (D)."},{"n":60,"q":"What goal is the woman trying to achieve?","qvi":"Người phụ nữ đang cố đạt mục tiêu gì?","opts":["A sales increase","Larger production capacity","Complete customer satisfaction","Becoming an effective leader"],"vi":["Tăng doanh số","Tăng năng lực sản xuất","Sự hài lòng trọn vẹn của khách hàng","Trở thành nhà lãnh đạo giỏi"],"ans":"C","xp":"'with a goal of utmost customer satisfaction' → (C). utmost = complete."},{"n":61,"q":"According to the woman, what will take place in the summer?","qvi":"Theo người phụ nữ, điều gì sẽ diễn ra vào mùa hè?","opts":["A seating class will be introduced.","Peak season discounts will be offered.","A new rewards program will begin.","New in-flight meal options will be added."],"vi":["Một hạng ghế mới sẽ được ra mắt.","Sẽ có giảm giá mùa cao điểm.","Chương trình tích điểm mới sẽ bắt đầu.","Sẽ thêm lựa chọn suất ăn trên máy bay."],"ans":"A","xp":"'We will introduce a new fare class, Premium Economy... before the summer peak travel time' → ra mắt hạng ghế mới → (A)."}],"a":"XC-T07-59-61.mp3"},{"ns":[62,64],"script":[["M","Good morning, and welcome to the Roxbury Clinic. Do you have a scheduled appointment?","Chào buổi sáng, chào mừng đến phòng khám Roxbury. Chị có lịch hẹn trước không?"],["W","I'm from Hinkle Designs. My site manager should have called you this morning.","Tôi đến từ Hinkle Designs. Quản lý của tôi chắc đã gọi cho anh sáng nay."],["M","Oh, yes. I just got off the phone with him.","À vâng. Tôi vừa nói chuyện điện thoại với anh ấy xong."],["W","Great. So you know that I'm delivering several boxes of eyeglasses for your on-site stock. Should I just take them up to your display area?","Tốt quá. Vậy anh biết tôi đang giao mấy thùng kính mắt cho kho của phòng khám rồi. Tôi mang thẳng lên khu trưng bày nhé?"],["M","Actually, we'd like you to store them in our billing department for now until we have time to sort them out.","Thật ra chúng tôi muốn chị để chúng ở phòng thanh toán trước, đến khi có thời gian phân loại."],["W","Okay. I'll get everything from my truck and then go up there.","Được. Tôi sẽ lấy hết đồ trên xe rồi lên đó."]],"qs":[{"n":62,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A site manager","An eye doctor","A designer","A receptionist"],"vi":["Quản lý công trường","Bác sĩ nhãn khoa","Nhà thiết kế","Nhân viên lễ tân"],"ans":"D","xp":"'welcome to the Roxbury Clinic. Do you have a scheduled appointment?' → người tiếp đón ở phòng khám → lễ tân → (D)."},{"n":63,"q":"Why does the woman make a visit?","qvi":"Vì sao người phụ nữ đến?","opts":["To give some checklists","To get her eyes tested","To drop off some goods","To show clothing samples"],"vi":["Để đưa danh sách kiểm tra","Để khám mắt","Để giao hàng","Để cho xem mẫu quần áo"],"ans":"C","xp":"'I'm delivering several boxes of eyeglasses' → giao hàng → (C)."},{"n":64,"q":"Look at the graphic. Where is the woman told to go?","qvi":"Nhìn hình. Người phụ nữ được bảo đi đâu?","opts":["To the 1st floor","To the 2nd floor","To the 3rd floor","To the 4th floor"],"vi":["Lên tầng 1","Lên tầng 2","Lên tầng 3","Lên tầng 4"],"ans":"D","xp":"'store them in our billing department'; bảng: Billing department ở 4th Floor → (D). (B) tầng 2 là khu trưng bày (cô định lên đó nhưng được bảo khác)."}],"a":"XC-T07-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","So, did you get the e-mail from the parks director? The concession stand in the roller coaster section of the park is going to be closed down for a month while it undergoes renovations.","Này, anh nhận e-mail của giám đốc công viên chưa? Quầy bán đồ ăn ở khu tàu lượn siêu tốc sẽ đóng cửa một tháng để sửa chữa."],["M","I saw that. It's about time that some improvements are made to that site.","Tôi thấy rồi. Cũng đến lúc nơi đó được cải tạo."],["W","Yeah, I completely agree.","Ừ, tôi hoàn toàn đồng ý."],["M","But won't it be confusing for the people who visit the park? They'll see it on our park directory and try to go there.","Nhưng như vậy khách đến công viên có bị bối rối không? Họ sẽ thấy nó trên bảng chỉ dẫn và tìm đến đó."],["W","That shouldn't be an issue. Jessie will design a new map to hang at the main entrance and around the park. It'll show the temporary change.","Chuyện đó không thành vấn đề. Jessie sẽ thiết kế bản đồ mới treo ở lối vào chính và khắp công viên. Nó sẽ thể hiện thay đổi tạm thời này."]],"qs":[{"n":65,"q":"Look at the graphic. Which concession stand will be temporarily closed?","qvi":"Nhìn hình. Quầy đồ ăn nào sẽ tạm đóng cửa?","opts":["Snacks Express","Crunch and Munch","Scoops Plus","Tiny Treats"],"vi":["Snacks Express","Crunch and Munch","Scoops Plus","Tiny Treats"],"ans":"B","xp":"'The concession stand in the roller coaster section' → trên bản đồ, quầy nằm trong khu Roller Coaster World là Crunch and Munch → (B)."},{"n":66,"q":"What problem does the man mention?","qvi":"Người đàn ông nêu vấn đề gì?","opts":["Parking will be limited.","Construction will be noisy.","Attendance may decline.","Visitors could be confused."],"vi":["Chỗ đỗ xe sẽ hạn chế.","Thi công sẽ ồn.","Lượng khách có thể giảm.","Khách có thể bị bối rối."],"ans":"D","xp":"'won't it be confusing for the people who visit the park?' → khách bị bối rối → (D)."},{"n":67,"q":"What does the woman say that Jessie will do?","qvi":"Người phụ nữ nói Jessie sẽ làm gì?","opts":["Change a policy","Create a map of the park","Hire a temporary worker","Give a tour of the site"],"vi":["Thay đổi chính sách","Làm bản đồ công viên","Thuê nhân viên tạm thời","Dẫn tham quan"],"ans":"B","xp":"'Jessie will design a new map to hang at the main entrance' → làm bản đồ → (B)."}],"a":"XC-T07-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Hello. I'm interested in signing up for your business development workshop. I tried registering online several times this morning, but it didn't move to the billing page, so I just decided to give a call.","Xin chào. Tôi muốn đăng ký hội thảo phát triển kinh doanh của quý vị. Sáng nay tôi thử đăng ký trực tuyến mấy lần nhưng không chuyển sang được trang thanh toán, nên tôi quyết định gọi điện."],["W","Oh, I'm sorry about the inconvenience, sir. We are working on it now, and it will be back to normal in a couple of hours. Will you attend the entire workshop?","Ồ, xin lỗi vì sự bất tiện, thưa anh. Chúng tôi đang khắc phục và vài tiếng nữa sẽ bình thường lại. Anh sẽ tham dự toàn bộ hội thảo chứ?"],["M","Unfortunately, I have to miss the first day of the event, and general seating is fine with me.","Tiếc là tôi phải vắng ngày đầu tiên, và chỗ ngồi thường là được rồi."],["W","All right. Next, I'll help you make the payment. Would you tell me which payment method you prefer?","Được. Tiếp theo tôi sẽ giúp anh thanh toán. Anh cho biết anh muốn thanh toán bằng cách nào?"]],"qs":[{"n":68,"q":"What problem does the man mention?","qvi":"Người đàn ông nêu vấn đề gì?","opts":["A bill was not received.","A phone call was not answered.","A workshop's dates have changed.","A Web site contained an error."],"vi":["Chưa nhận được hóa đơn.","Cuộc gọi không được trả lời.","Ngày hội thảo đã thay đổi.","Trang web bị lỗi."],"ans":"D","xp":"'I tried registering online several times... but it didn't move to the billing page' → trang web bị lỗi → (D)."},{"n":69,"q":"Look at the graphic. How much should the man pay?","qvi":"Nhìn hình. Người đàn ông phải trả bao nhiêu?","opts":["£80","£120","£140","£200"],"vi":["80 bảng","120 bảng","140 bảng","200 bảng"],"ans":"A","xp":"Ông vắng ngày đầu → chỉ dự một ngày (One-day Pass) và chọn 'general seating'; bảng: One-day Pass – General Seating = £80 → (A)."},{"n":70,"q":"What is the man asked to do?","qvi":"Người đàn ông được yêu cầu làm gì?","opts":["Choose a payment option","Print a receipt","Provide an e-mail address","Update a membership status"],"vi":["Chọn cách thanh toán","In biên lai","Cung cấp e-mail","Cập nhật tình trạng hội viên"],"ans":"A","xp":"'Would you tell me which payment method you prefer?' → chọn cách thanh toán → (A)."}],"a":"XC-T07-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Welcome to Harriet's Outlet, the best place to find deals on home appliances you need in your home. Check out our current clearance sale in Section A. It features blenders, microwaves, coffee machines, and toasters. Please keep in mind that next month our store will undergo renovations. If there are any recommendations you would like to make regarding our new store layout, please put them in the suggestion box located next to the exit door by the end of this month. You will automatically be entered into our big year-end raffle event. As always, thank you for shopping with us. We'll see you next time.","Chào mừng quý khách đến Harriet's Outlet, nơi tốt nhất để tìm giá hời cho các thiết bị gia dụng cần thiết trong nhà. Hãy xem đợt bán thanh lý hàng tồn đang diễn ra ở Khu A, gồm máy xay sinh tố, lò vi sóng, máy pha cà phê và máy nướng bánh mì. Xin lưu ý tháng sau cửa hàng sẽ được cải tạo. Nếu quý khách có góp ý về cách bố trí cửa hàng mới, vui lòng bỏ vào hộp góp ý cạnh cửa ra trước cuối tháng này. Quý khách sẽ tự động được tham gia đợt rút thăm trúng thưởng lớn cuối năm. Như mọi khi, cảm ơn quý khách đã mua sắm. Hẹn gặp lại lần sau."]],"qs":[{"n":71,"q":"Where is the announcement being made?","qvi":"Thông báo được phát ở đâu?","opts":["At a clothing store","At a market","At a conference center","At a home appliances store"],"vi":["Ở cửa hàng quần áo","Ở chợ","Ở trung tâm hội nghị","Ở cửa hàng đồ gia dụng"],"ans":"D","xp":"'Welcome to Harriet's Outlet, the best place to find deals on home appliances' → cửa hàng đồ gia dụng → (D)."},{"n":72,"q":"What event is taking place in Section A?","qvi":"Sự kiện gì đang diễn ra ở Khu A?","opts":["A product demonstration","Renovation work","A clearance sale","A lottery"],"vi":["Trình diễn sản phẩm","Cải tạo","Bán thanh lý hàng tồn","Xổ số"],"ans":"C","xp":"'Check out our current clearance sale in Section A' → (C). (B) cải tạo là tháng sau, (D) rút thăm cuối năm."},{"n":73,"q":"What are listeners asked to do by the end of the month?","qvi":"Người nghe được yêu cầu làm gì trước cuối tháng?","opts":["Submit suggestions","Join a membership","Fill out a survey form","Sign up for a newsletter"],"vi":["Nộp góp ý","Đăng ký hội viên","Điền phiếu khảo sát","Đăng ký nhận bản tin"],"ans":"A","xp":"'please put them (recommendations) in the suggestion box... by the end of this month' → nộp góp ý → (A)."}],"a":"XC-T07-71-73.mp3"},{"ns":[74,76],"script":[["M","Hello Mr. Watts, this is Eric from Stockton Auto Repair. I completed the oil change that you brought your car in for, but there are some other things that I noticed while I was conducting a bumper-to-bumper check. Your tires and brake pads are all getting a bit worn out. Since those things would cost extra money, I wanted to get your permission before doing the extra work. Once you get this, please call me back to authorize it. Talk to you soon.","Xin chào ông Watts, tôi là Eric từ tiệm sửa xe Stockton Auto Repair. Tôi đã thay dầu xong cho chiếc xe ông mang đến, nhưng khi kiểm tra toàn bộ xe, tôi phát hiện vài vấn đề khác. Lốp và má phanh đều đã hơi mòn. Vì những việc này sẽ tốn thêm tiền, tôi muốn xin phép ông trước khi làm thêm. Khi nhận được tin nhắn này, xin gọi lại cho tôi để đồng ý. Hẹn nói chuyện sau."]],"qs":[{"n":74,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A real estate agent","A car repairman","A security guard","An assembly line worker"],"vi":["Nhân viên bất động sản","Thợ sửa ô tô","Nhân viên bảo vệ","Công nhân dây chuyền lắp ráp"],"ans":"B","xp":"'this is Eric from Stockton Auto Repair. I completed the oil change...' → thợ sửa ô tô → (B)."},{"n":75,"q":"What is the speaker calling about?","qvi":"Người nói gọi điện về việc gì?","opts":["An office relocation","A new car model","Additional work","A free service"],"vi":["Việc chuyển văn phòng","Mẫu xe mới","Công việc phát sinh thêm","Dịch vụ miễn phí"],"ans":"C","xp":"'Since those things would cost extra money, I wanted to get your permission before doing the extra work' → việc làm thêm → (C). extra = additional."},{"n":76,"q":"Why is the listener asked to return a call?","qvi":"Vì sao người nghe được đề nghị gọi lại?","opts":["To get a discount","To grant permission","To pay with a credit card","To reschedule an inspection"],"vi":["Để được giảm giá","Để cho phép","Để trả bằng thẻ tín dụng","Để dời lịch kiểm tra"],"ans":"B","xp":"'please call me back to authorize it' → gọi lại để cho phép → (B). authorize = grant permission."}],"a":"XC-T07-74-76.mp3"},{"ns":[77,79],"script":[["W","Tracy Banks here with the latest in technology news. Listening to music just got even more convenient. This wireless earpiece made by Soundbox is compatible with all kinds of devices with a Bluetooth function. Its most special feature is its waterproof design. Surprisingly, you can listen to music or talk with your friends even while in a swimming pool. As a way of marketing this product, Soundbox is offering a one-week free trial period. If you are not satisfied with it, you can just bring it back to the store you got it from. Since there is nothing to lose, everyone should take advantage of this chance for a free trial. They're available at electronics stores across the country.","Tracy Banks với tin công nghệ mới nhất. Nghe nhạc giờ còn tiện hơn nữa. Tai nghe không dây của Soundbox tương thích với mọi thiết bị có Bluetooth. Tính năng đặc biệt nhất là thiết kế chống nước. Thật bất ngờ, bạn có thể nghe nhạc hay nói chuyện với bạn bè ngay cả khi đang ở hồ bơi. Để quảng bá sản phẩm, Soundbox cho dùng thử miễn phí một tuần. Nếu không hài lòng, bạn chỉ cần mang trả lại cửa hàng đã mua. Vì chẳng mất gì, mọi người nên tận dụng cơ hội dùng thử miễn phí này. Sản phẩm có bán tại các cửa hàng điện tử trên toàn quốc."]],"qs":[{"n":77,"q":"What product is the speaker introducing?","qvi":"Người nói giới thiệu sản phẩm gì?","opts":["A laptop computer","A mobile phone","Earphones","A wristwatch"],"vi":["Máy tính xách tay","Điện thoại di động","Tai nghe","Đồng hồ đeo tay"],"ans":"C","xp":"'This wireless earpiece made by Soundbox' → tai nghe → (C)."},{"n":78,"q":"What makes the product special?","qvi":"Điều gì làm sản phẩm đặc biệt?","opts":["Its durability","Its high sound quality","Its longer battery life","Its waterproof design"],"vi":["Độ bền","Chất lượng âm thanh cao","Pin lâu hơn","Thiết kế chống nước"],"ans":"D","xp":"'Its most special feature is its waterproof design' → (D)."},{"n":79,"q":"What does the speaker recommend that listeners do?","qvi":"Người nói khuyên người nghe làm gì?","opts":["Go to a manufacturer's Web site","Try out a product for free","Refer to a user's manual","Purchase an extended warranty"],"vi":["Vào web nhà sản xuất","Dùng thử sản phẩm miễn phí","Xem sách hướng dẫn","Mua thêm bảo hành"],"ans":"B","xp":"'everyone should take advantage of this chance for a free trial' → dùng thử miễn phí → (B)."}],"a":"XC-T07-77-79.mp3"},{"ns":[80,82],"script":[["M","Hi, I'm glad you all could make it. I called you here today to talk about a job opening that requires your immediate attention. Local store manager Ms. Connolly has just announced that she will be leaving our company in two weeks for personal reasons, and the management would like to recruit from within the company. As you already know, we usually have a full month to fill a position from inside, but this time, we have two weeks. Wilfred, I want you to post this opening on the company's Web site with the required qualifications and detailed responsibilities as soon as possible.","Chào mọi người, rất vui vì mọi người đều đến được. Hôm nay tôi gọi mọi người đến để bàn về một vị trí trống cần xử lý ngay. Quản lý cửa hàng khu vực, bà Connolly, vừa thông báo sẽ nghỉ việc sau hai tuần vì lý do cá nhân, và ban lãnh đạo muốn tuyển người trong nội bộ công ty. Như mọi người biết, thường chúng ta có trọn một tháng để tuyển nội bộ, nhưng lần này chỉ có hai tuần. Wilfred, tôi muốn anh đăng vị trí này lên trang web công ty kèm yêu cầu trình độ và mô tả trách nhiệm chi tiết càng sớm càng tốt."]],"qs":[{"n":80,"q":"Why did the speaker call the meeting?","qvi":"Vì sao người nói triệu tập cuộc họp?","opts":["To promote an employee","To give a sales report","To discuss an urgent task","To congratulate an achievement"],"vi":["Để thăng chức một nhân viên","Để báo cáo doanh số","Để bàn một việc gấp","Để chúc mừng thành tích"],"ans":"C","xp":"'to talk about a job opening that requires your immediate attention' → việc cần làm gấp → (C)."},{"n":81,"q":"Why does the speaker say, \"we have two weeks\"?","qvi":"Vì sao người nói nói \"chúng ta có hai tuần\"?","opts":["To warn of strong competition","To express concern about insufficient time","To request a deadline extension","To ask for extra workers"],"vi":["Để cảnh báo cạnh tranh mạnh","Để bày tỏ lo ngại thiếu thời gian","Để xin gia hạn","Để xin thêm người"],"ans":"B","xp":"'we usually have a full month to fill a position from inside, but this time, we have two weeks' → chỉ có nửa thời gian thường lệ → lo thiếu thời gian → (B)."},{"n":82,"q":"What does the speaker tell Wilfred to do?","qvi":"Người nói bảo Wilfred làm gì?","opts":["Recommend a candidate","Collect some résumés","Write a job opening online","Apply for a position"],"vi":["Giới thiệu ứng viên","Thu thập hồ sơ","Đăng tin tuyển dụng lên mạng","Ứng tuyển một vị trí"],"ans":"C","xp":"'Wilfred, I want you to post this opening on the company's Web site' → đăng tin tuyển dụng trực tuyến → (C)."}],"a":"XC-T07-80-82.mp3"},{"ns":[83,85],"script":[["W","As you may have heard, we will be restructuring our staff next month. We hope this will improve efficiency and teamwork at the office by maximizing the unique skills of each person. Some teams will be combined, and others will be eliminated, with the members being sent to other groups. Many of you may have a feeling of stress as you make the transition, but it won't last forever. In a short time, you'll be fully adjusted. I've outlined all of the changes in this packet. Please look it over to ensure that you understand everything.","Như mọi người có thể đã nghe, tháng sau chúng ta sẽ tái cơ cấu nhân sự. Chúng tôi hy vọng điều này sẽ cải thiện hiệu quả và tinh thần làm việc nhóm bằng cách phát huy tối đa kỹ năng riêng của mỗi người. Một số nhóm sẽ được gộp lại, một số nhóm sẽ bị giải thể và thành viên được chuyển sang nhóm khác. Nhiều người có thể thấy căng thẳng trong giai đoạn chuyển đổi, nhưng điều đó sẽ không kéo dài mãi. Chẳng bao lâu mọi người sẽ hoàn toàn thích nghi. Tôi đã tóm tắt mọi thay đổi trong tập tài liệu này. Hãy đọc kỹ để chắc chắn hiểu hết."]],"qs":[{"n":83,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu bàn về điều gì?","opts":["Implementing staff training","Reorganizing some teams","Negotiating some contracts","Adjusting a payment system"],"vi":["Triển khai đào tạo nhân viên","Tổ chức lại một số nhóm","Đàm phán hợp đồng","Điều chỉnh hệ thống trả lương"],"ans":"B","xp":"'we will be restructuring our staff... Some teams will be combined, and others will be eliminated' → tổ chức lại các nhóm → (B)."},{"n":84,"q":"Why does the speaker say, \"it won't last forever\"?","qvi":"Vì sao người nói nói \"điều đó sẽ không kéo dài mãi\"?","opts":["To recommend fast action","To provide a warning","To suggest an alternative","To give encouragement"],"vi":["Để khuyên hành động nhanh","Để cảnh báo","Để đề xuất phương án khác","Để động viên"],"ans":"D","xp":"Câu nói đi sau 'Many of you may have a feeling of stress' và trước 'In a short time, you'll be fully adjusted' → trấn an, động viên → (D)."},{"n":85,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Review some information","Provide an update","Share their opinions","Print some documents"],"vi":["Xem kỹ thông tin","Cập nhật tình hình","Chia sẻ ý kiến","In tài liệu"],"ans":"A","xp":"'I've outlined all of the changes in this packet. Please look it over' → xem kỹ thông tin → (A)."}],"a":"XC-T07-83-85.mp3"},{"ns":[86,88],"script":[["","Welcome to today's tour of CrystalView's TV manufacturing plant. As you may know, our LED screens have higher quality ratings than any other TV manufacturer's. During this tour, you will get a chance to see how these LED screens are produced. After that, you will also hear from Benjamin Farrell, the chief researcher who has developed our company's unique screens. He will give a short talk on how new technologies can be adapted into a product. There will also be time for general questions. Now, before we get started, you all must put on these gloves and a cap for sanitary purposes. Everyone on the production floor is required to wear them at all times.","Chào mừng quý vị đến với buổi tham quan nhà máy sản xuất TV của CrystalView hôm nay. Như quý vị có thể biết, màn hình LED của chúng tôi được đánh giá chất lượng cao hơn mọi nhà sản xuất TV khác. Trong buổi tham quan, quý vị sẽ được xem cách sản xuất những màn hình LED này. Sau đó, quý vị sẽ nghe Benjamin Farrell, trưởng nhóm nghiên cứu đã phát triển dòng màn hình độc đáo của công ty, nói chuyện ngắn về cách đưa công nghệ mới vào sản phẩm. Sẽ có thời gian cho các câu hỏi chung. Bây giờ, trước khi bắt đầu, mọi người phải đeo găng tay và đội mũ này để đảm bảo vệ sinh. Ai ở trong khu sản xuất cũng phải luôn đeo chúng."]],"qs":[{"n":86,"q":"What product is featured on the tour?","qvi":"Buổi tham quan giới thiệu sản phẩm gì?","opts":["Televisions","Digital cameras","Smart watches","Computer monitors"],"vi":["Ti vi","Máy ảnh kỹ thuật số","Đồng hồ thông minh","Màn hình máy tính"],"ans":"A","xp":"'today's tour of CrystalView's TV manufacturing plant' → TV → (A)."},{"n":87,"q":"Who is Benjamin Farrell?","qvi":"Benjamin Farrell là ai?","opts":["An engineer","A production manager","A film critic","A news reporter"],"vi":["Kỹ sư","Quản lý sản xuất","Nhà phê bình phim","Phóng viên"],"ans":"A","xp":"'Benjamin Farrell, the chief researcher who has developed our company's unique screens' → người nghiên cứu, phát triển màn hình = kỹ sư → (A)."},{"n":88,"q":"What are the listeners asked to do?","qvi":"Người nghe được yêu cầu làm gì?","opts":["Take a photo","Wear sanitary gear","Watch a film","Avoid touching any equipment"],"vi":["Chụp ảnh","Mặc đồ bảo hộ vệ sinh","Xem phim","Không chạm vào thiết bị"],"ans":"B","xp":"'you all must put on these gloves and a cap for sanitary purposes' → đeo đồ bảo hộ vệ sinh → (B)."}],"a":"XC-T07-86-88.mp3"},{"ns":[89,91],"script":[["M","Hi, Kamiko. It's Eduardo. I'm trying to make the final arrangements for our company's year-end banquet at Granada Hall. I need to tell the caterer exactly how many people will be in attendance. I've sent nearly 100 invitations to employees. The problem is, I've just looked at who has written back. I only have ten cards. Since I need a final head count by tomorrow, I'd like to ask a favor of you. Could you please talk to the people on your team and find out who is going? I'm asking every department manager to do this. Thanks!","Chào Kamiko, tôi là Eduardo đây. Tôi đang sắp xếp những khâu cuối cho tiệc tất niên của công ty ở Granada Hall. Tôi cần báo cho bên cung cấp đồ ăn chính xác số người tham dự. Tôi đã gửi gần 100 thiệp mời cho nhân viên. Vấn đề là tôi vừa xem ai đã hồi âm. Tôi mới chỉ nhận được mười thiệp. Vì tôi cần con số chính xác trước ngày mai, tôi muốn nhờ chị một việc. Chị có thể hỏi các thành viên trong nhóm xem ai sẽ đi không? Tôi đang nhờ tất cả trưởng phòng làm việc này. Cảm ơn chị!"]],"qs":[{"n":89,"q":"What type of event is the speaker planning?","qvi":"Người nói đang lên kế hoạch cho sự kiện gì?","opts":["A grand opening","A recruitment drive","A company dinner","A training session"],"vi":["Lễ khai trương","Đợt tuyển dụng","Bữa tiệc công ty","Buổi đào tạo"],"ans":"C","xp":"'our company's year-end banquet at Granada Hall' → tiệc tối của công ty → (C)."},{"n":90,"q":"What does the speaker suggest when he says, \"I only have ten cards\"?","qvi":"Người nói ngụ ý gì khi nói \"tôi mới chỉ nhận được mười thiệp\"?","opts":["Many people did not respond to an invitation.","An order for supplies needs to be placed.","Some merchandise is no longer available.","A mailing list was incorrect."],"vi":["Nhiều người chưa hồi âm thiệp mời.","Cần đặt mua vật tư.","Một số hàng không còn.","Danh sách gửi thư bị sai."],"ans":"A","xp":"Gửi gần 100 thiệp nhưng 'I've just looked at who has written back. I only have ten cards' → nhiều người chưa trả lời → (A)."},{"n":91,"q":"What is the listener asked to do?","qvi":"Người nghe được nhờ làm gì?","opts":["Speak to her coworkers","Revise a budget proposal","E-mail the department managers","Find a new venue"],"vi":["Nói chuyện với đồng nghiệp","Sửa đề xuất ngân sách","E-mail cho các trưởng phòng","Tìm địa điểm mới"],"ans":"A","xp":"'Could you please talk to the people on your team and find out who is going?' → nói chuyện với đồng nghiệp → (A)."}],"a":"XC-T07-89-91.mp3"},{"ns":[92,94],"script":[["W","Good morning, everyone. If you haven't heard, the reviews are in on our latest tablet device. Thanks to the advanced software that we developed, people are loving our product. Let's give a round of applause for ourselves, the development team. Customers who were surveyed said that they were most impressed by our product's interface, which is very user-friendly. Next month is the company's annual awards dinner to be held at the headquarters office, and we have received a special invitation to attend it. HR will provide more details about travel arrangements later this week.","Chào buổi sáng mọi người. Nếu ai chưa nghe thì đã có đánh giá về chiếc máy tính bảng mới nhất của chúng ta. Nhờ phần mềm tiên tiến chúng ta phát triển, mọi người rất yêu thích sản phẩm. Hãy tự vỗ tay cho chính mình, đội phát triển. Khách hàng được khảo sát cho biết họ ấn tượng nhất với giao diện rất dễ dùng của sản phẩm. Tháng sau là tiệc trao giải thường niên của công ty tổ chức tại trụ sở chính, và chúng ta đã nhận được lời mời đặc biệt tham dự. Bộ phận Nhân sự sẽ cung cấp thêm thông tin về việc đi lại trong tuần này."]],"qs":[{"n":92,"q":"Who is being recognized?","qvi":"Ai đang được ghi nhận?","opts":["Sales team members","Software developers","Graphic designers","Customer service representatives"],"vi":["Thành viên đội bán hàng","Nhà phát triển phần mềm","Nhà thiết kế đồ họa","Nhân viên chăm sóc khách hàng"],"ans":"B","xp":"'Thanks to the advanced software that we developed... a round of applause for ourselves, the development team' → nhà phát triển phần mềm → (B)."},{"n":93,"q":"According to the speaker, what do customers like about the latest product?","qvi":"Theo người nói, khách hàng thích gì ở sản phẩm mới nhất?","opts":["The size of the screen","The battery life","The wireless connection","The user interface"],"vi":["Kích thước màn hình","Thời lượng pin","Kết nối không dây","Giao diện người dùng"],"ans":"D","xp":"'most impressed by our product's interface, which is very user-friendly' → (D)."},{"n":94,"q":"What will the listeners most likely do next month?","qvi":"Tháng sau người nghe nhiều khả năng sẽ làm gì?","opts":["Attend an awards ceremony","Review sales figures","Transfer to the company headquarters","Interview new job applicants"],"vi":["Dự lễ trao giải","Xem số liệu bán hàng","Chuyển về trụ sở chính","Phỏng vấn ứng viên"],"ans":"A","xp":"'Next month is the company's annual awards dinner... we have received a special invitation to attend it' → dự lễ trao giải → (A). (C) chỉ đến trụ sở dự tiệc, không chuyển công tác."}],"a":"XC-T07-92-94.mp3"},{"ns":[95,97],"script":[["","Once again, everyone, on behalf of the Shanghai Tour Company, I'm sorry that our bus didn't reach the hotel until seven even though it was scheduled for six. However, the staff is ready to check you in quickly, and you have the rest of the evening to relax. I've passed out the schedule for tomorrow. You'll probably want to take a lot of photos, so don't forget to plug your phone or camera into the charger tonight. And due to an unexpected closure, we won't be able to do the second afternoon activity tomorrow. Instead, we'll go to the Jindo Theater to view a traditional dance performance. I'll be in room 303 if you have any questions.","Một lần nữa, thay mặt Công ty Du lịch Thượng Hải, tôi xin lỗi vì xe buýt đến khách sạn lúc 7 giờ dù dự kiến là 6 giờ. Tuy nhiên, nhân viên khách sạn đã sẵn sàng làm thủ tục nhanh cho mọi người, và mọi người có cả buổi tối để nghỉ ngơi. Tôi đã phát lịch trình ngày mai. Chắc mọi người sẽ muốn chụp nhiều ảnh, nên tối nay đừng quên sạc điện thoại hoặc máy ảnh. Và do một nơi đóng cửa đột xuất, ngày mai chúng ta sẽ không thể tham gia hoạt động thứ hai buổi chiều. Thay vào đó, chúng ta sẽ đến nhà hát Jindo xem múa truyền thống. Tôi ở phòng 303 nếu ai có câu hỏi."]],"qs":[{"n":95,"q":"Why does the speaker apologize?","qvi":"Vì sao người nói xin lỗi?","opts":["The tour was overbooked.","Some hotel rooms were not ready.","A bus arrived at a site late.","Some participants were overcharged."],"vi":["Tour bị đặt quá số chỗ.","Một số phòng chưa sẵn sàng.","Xe buýt đến nơi muộn.","Một số người bị tính tiền quá."],"ans":"C","xp":"'I'm sorry that our bus didn't reach the hotel until seven even though it was scheduled for six' → xe đến muộn → (C)."},{"n":96,"q":"What does the speaker remind the listeners to do?","qvi":"Người nói nhắc người nghe làm gì?","opts":["Try some local foods","Charge an electronic device","Bring a form of identification","Pick up a map"],"vi":["Ăn thử món địa phương","Sạc thiết bị điện tử","Mang giấy tờ tùy thân","Lấy bản đồ"],"ans":"B","xp":"'don't forget to plug your phone or camera into the charger tonight' → sạc thiết bị → (B)."},{"n":97,"q":"Look at the graphic. Which activity has been changed?","qvi":"Nhìn hình. Hoạt động nào đã bị thay đổi?","opts":["Botanical Gardens","Sculpture Museum","Castle Tour","Crafts Market"],"vi":["Vườn bách thảo","Bảo tàng điêu khắc","Tham quan lâu đài","Chợ đồ thủ công"],"ans":"D","xp":"'we won't be able to do the second afternoon activity tomorrow'; lịch buổi chiều: 2 P.M. Castle Tour, 4 P.M. Crafts Market → hoạt động thứ hai buổi chiều là Crafts Market → (D)."}],"a":"XC-T07-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","If you're working on a home improvement project, stop by Peterson's for everything you need. For your convenience, we changed our closing time last week, so now we are open one hour later. And our reputation for always having great deals on our goods is well deserved. You'll save more money at Peterson's than anywhere else. For further savings, you can also download coupons from our Web site for half off lumber at the Farrison branch and buy-one-get-one-free power tools at the Westwater branch. We hope to see you at Peterson's.","Nếu bạn đang làm dự án sửa sang nhà cửa, hãy ghé Peterson's để có mọi thứ cần thiết. Để thuận tiện cho bạn, tuần trước chúng tôi đã đổi giờ đóng cửa, giờ chúng tôi mở cửa muộn hơn một tiếng. Và danh tiếng luôn có giá hời của chúng tôi là hoàn toàn xứng đáng. Bạn sẽ tiết kiệm ở Peterson's nhiều hơn bất cứ đâu. Để tiết kiệm thêm, bạn có thể tải phiếu giảm giá trên trang web: giảm nửa giá gỗ ở chi nhánh Farrison và mua một tặng một dụng cụ điện ở chi nhánh Westwater. Mong được gặp bạn ở Peterson's."]],"qs":[{"n":98,"q":"What has Peterson's recently done?","qvi":"Gần đây Peterson's đã làm gì?","opts":["Introduced a new product","Added a delivery service","Extended its business hours","Hired more staff members"],"vi":["Ra mắt sản phẩm mới","Thêm dịch vụ giao hàng","Kéo dài giờ mở cửa","Tuyển thêm nhân viên"],"ans":"C","xp":"'we changed our closing time last week, so now we are open one hour later' → kéo dài giờ mở cửa → (C)."},{"n":99,"q":"According to the speaker, what is Peterson's known for?","qvi":"Theo người nói, Peterson's nổi tiếng về điều gì?","opts":["Its low prices","Its wide selection","Its convenient locations","Its helpful staff"],"vi":["Giá thấp","Nhiều lựa chọn","Vị trí thuận tiện","Nhân viên nhiệt tình"],"ans":"A","xp":"'our reputation for always having great deals on our goods... You'll save more money' → giá thấp → (A)."},{"n":100,"q":"Look at the graphic. Where can the coupon be used?","qvi":"Nhìn hình. Phiếu giảm giá dùng được ở đâu?","opts":["At the Lake City branch","At the Grantwood branch","At the Farrison branch","At the Westwater branch"],"vi":["Chi nhánh Lake City","Chi nhánh Grantwood","Chi nhánh Farrison","Chi nhánh Westwater"],"ans":"C","xp":"Phiếu: '50% off from all lumber supplies'; bài nói: 'half off lumber at the Farrison branch' → (C)."}],"a":"XC-T07-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"All buyers from Richard's Auto Dealership can have their cars ------- inspected based on their maintenance schedules.","opts":["regular","regularity","regulation","regularly"],"ans":"D","xp":"Từ loại. Cấu trúc 'have + tân ngữ + V3' (nhờ ai làm gì): 'have their cars ------- inspected' → chỗ trống bổ nghĩa cho 'inspected' cần trạng từ (D) regularly 'thường xuyên'. (A) tính từ, (B)(C) danh từ.\nDịch: Mọi khách mua xe ở đại lý ô tô Richard có thể mang xe đi kiểm tra định kỳ theo lịch bảo dưỡng."},{"n":102,"q":"This diet program assists and encourages ------- to lead a healthy lifestyle.","opts":["your","yours","you","yourselves"],"ans":"C","xp":"Đại từ. Sau động từ 'encourages' cần tân ngữ; cấu trúc encourage + O + to V → (C) you. (A) your là tính từ sở hữu (cần danh từ theo sau), (B) yours 'của bạn' không hợp nghĩa, (D) yourselves chỉ dùng khi chủ ngữ cũng là 'you'.\nDịch: Chương trình ăn kiêng này hỗ trợ và khuyến khích bạn sống lành mạnh."},{"n":103,"q":"Access to River Road has been restricted ------- heavy rain and flood warnings.","opts":["though","wherever","because of","such as"],"ans":"C","xp":"Giới từ/liên từ. Sau chỗ trống là cụm danh từ 'heavy rain and flood warnings' (không có động từ) → cần giới từ chỉ nguyên nhân (C) because of 'vì'. (A) though, (B) wherever là liên từ (cần mệnh đề), (D) such as 'chẳng hạn' không hợp nghĩa.\nDịch: Đường River Road đã bị hạn chế đi lại vì mưa lớn và cảnh báo lũ."},{"n":104,"q":"After this baseball season ends, the ------- of Cooperstown Ball Park's seats will begin.","opts":["replaces","replaceable","replacement","replaced"],"ans":"C","xp":"Từ loại. Sau 'the' và trước 'of' cần danh từ → (C) replacement 'việc thay thế'. (A) động từ, (B) tính từ, (D) V3.\nDịch: Sau khi mùa bóng chày này kết thúc, việc thay ghế ở sân Cooperstown sẽ bắt đầu."},{"n":105,"q":"Residents were ------- of the plan to spend city funds on upgrading Hayden Park.","opts":["support","supportively","supportive","supporting"],"ans":"C","xp":"Từ loại. Sau 'were' cần tính từ; cấu trúc be supportive of = ủng hộ → (C). (A) động từ/danh từ, (B) trạng từ, (D) V-ing (be supporting cần tân ngữ trực tiếp, không đi với 'of').\nDịch: Người dân ủng hộ kế hoạch dùng ngân sách thành phố để nâng cấp công viên Hayden."},{"n":106,"q":"All events at Bedford Festivals are subject to change without prior -------.","opts":["notice","belief","need","report"],"ans":"A","xp":"Từ vựng. without prior notice = không báo trước → (A) notice. (B) belief 'niềm tin', (C) need 'nhu cầu', (D) report 'báo cáo' không hợp.\nDịch: Mọi sự kiện của Bedford Festivals có thể thay đổi mà không báo trước."},{"n":107,"q":"The opening ceremony is running later than expected, so the ------- morning sessions will be delayed for 20 minutes.","opts":["schedule","scheduled","scheduling","schedules"],"ans":"B","xp":"Từ loại. Giữa 'the' và cụm danh từ 'morning sessions' cần tính từ → (B) scheduled 'đã lên lịch' (V3 dùng như tính từ). (A)(D) động từ/danh từ, (C) V-ing không hợp nghĩa (các phiên không tự 'lên lịch').\nDịch: Lễ khai mạc kéo dài hơn dự kiến, nên các phiên buổi sáng đã lên lịch sẽ lùi 20 phút."},{"n":108,"q":"Fields of Friends, a gardening guidebook by Reader's House, will be ------- into multiple languages next year.","opts":["translated","organized","trained","involved"],"ans":"A","xp":"Từ vựng. be translated into + ngôn ngữ = được dịch sang → (A). (B) organized 'được tổ chức', (C) trained 'được đào tạo', (D) involved 'được liên quan' không đi với 'into multiple languages'.\nDịch: Fields of Friends, cuốn sách hướng dẫn làm vườn của Reader's House, sẽ được dịch sang nhiều thứ tiếng vào năm sau."},{"n":109,"q":"It is ------- to change your computer log-in password every three months for security purposes.","opts":["impressed","reluctant","mandatory","bountiful"],"ans":"C","xp":"Từ vựng. Cấu trúc It is + tính từ + to V: 'bắt buộc phải đổi mật khẩu' → (C) mandatory 'bắt buộc'. (A) impressed 'ấn tượng', (B) reluctant 'miễn cưỡng' (dùng cho người), (D) bountiful 'dồi dào'.\nDịch: Vì lý do bảo mật, bắt buộc phải đổi mật khẩu đăng nhập máy tính ba tháng một lần."},{"n":110,"q":"The server had to relay the diners' request to the kitchen ------- when he heard one of them was allergic to seafood.","opts":["swift","swifter","swiftly","swiftest"],"ans":"C","xp":"Từ loại. Câu đã đủ thành phần 'relay the diners' request to the kitchen' → chỗ trống bổ nghĩa cho động từ 'relay' cần trạng từ (C) swiftly 'nhanh chóng'. (A)(B)(D) là tính từ và dạng so sánh.\nDịch: Người phục vụ đã phải nhanh chóng chuyển yêu cầu của thực khách vào bếp khi nghe một người bị dị ứng hải sản."},{"n":111,"q":"According to the ------- of your warranty, all incurred expenses and fees will be covered.","opts":["repairs","comments","terms","cards"],"ans":"C","xp":"Từ vựng. the terms of your warranty = các điều khoản bảo hành → (C). (A) repairs 'việc sửa chữa', (B) comments 'bình luận', (D) cards 'thẻ' không hợp.\nDịch: Theo các điều khoản bảo hành của bạn, mọi chi phí phát sinh sẽ được chi trả."},{"n":112,"q":"Allison Barr gained professional ------- in customizing shoes through the apprenticeship at Harman's Footwear.","opts":["responsibility","feedback","expertise","foundation"],"ans":"C","xp":"Từ vựng. gain professional expertise = có được chuyên môn nghề nghiệp → (C). (A) responsibility 'trách nhiệm', (B) feedback 'phản hồi', (D) foundation 'nền tảng' không hợp với 'in customizing shoes'.\nDịch: Allison Barr có được chuyên môn thiết kế giày theo yêu cầu nhờ học việc ở Harman's Footwear."},{"n":113,"q":"The board of Jenkins Manufacturing announced its plan to reduce emissions by 20% ------- three years.","opts":["around","between","before","within"],"ans":"D","xp":"Giới từ. within + khoảng thời gian = trong vòng → 'within three years' (D). (A) around 'khoảng', (B) between cần 2 mốc, (C) before + mốc thời gian (không đi với khoảng 'three years').\nDịch: Ban lãnh đạo Jenkins Manufacturing công bố kế hoạch giảm 20% khí thải trong vòng ba năm."},{"n":114,"q":"Due to the financial crisis, ------- management has decided to sell the company to Geyser Corp.","opts":["we","our","us","ourselves"],"ans":"B","xp":"Đại từ. Trước danh từ 'management' cần tính từ sở hữu → (B) our. (A) chủ ngữ, (C) tân ngữ, (D) phản thân.\nDịch: Do khủng hoảng tài chính, ban quản lý của chúng tôi đã quyết định bán công ty cho Geyser Corp."},{"n":115,"q":"All employees of Bentley Chemical are eligible for full insurance benefits once they have ------- one full year at the company.","opts":["completed","expired","predicted","permitted"],"ans":"A","xp":"Từ vựng. complete one full year = làm đủ một năm → (A) completed. (B) expired 'hết hạn', (C) predicted 'dự đoán', (D) permitted 'cho phép' không hợp nghĩa.\nDịch: Mọi nhân viên của Bentley Chemical được hưởng đầy đủ bảo hiểm khi đã làm đủ một năm ở công ty."},{"n":116,"q":"Our company conducts employee performance reviews -------, during which employees can speak openly with their supervisors.","opts":["highly","boldly","clearly","annually"],"ans":"D","xp":"Từ vựng. Đánh giá nhân viên được tổ chức 'hằng năm' → (D) annually. (A) highly 'rất', (B) boldly 'mạnh dạn', (C) clearly 'rõ ràng' không hợp với 'conducts reviews'.\nDịch: Công ty chúng tôi đánh giá năng lực nhân viên hằng năm, khi đó nhân viên có thể nói chuyện cởi mở với cấp trên."},{"n":117,"q":"The market for digital investments is ------- despite the fact that many people still prefer stocks and gold.","opts":["emerge","emerged","emerging","emerges"],"ans":"C","xp":"Từ loại/thì. Sau 'is' cần tính từ hoặc V-ing; emerge là nội động từ nên không có bị động 'is emerged' → (C) emerging 'đang nổi lên'. (A)(D) động từ nguyên thể/chia, (B) V3.\nDịch: Thị trường đầu tư kỹ thuật số đang phát triển dù nhiều người vẫn thích cổ phiếu và vàng."},{"n":118,"q":"Booklets at Amherst Used Car contain a list of car brands and information that is ------- to payment options or car leases.","opts":["comparable","directed","skilled","relevant"],"ans":"D","xp":"Từ vựng. be relevant to = liên quan đến → (D). (A) comparable to 'có thể so sánh', (B) directed to 'hướng đến', (C) skilled 'lành nghề' (dùng cho người) không hợp.\nDịch: Tập sách ở Amherst Used Car có danh sách hãng xe và thông tin liên quan đến các hình thức thanh toán hay thuê xe."},{"n":119,"q":"The wrist watch developed for extreme sports enthusiasts is resistant against water, even ------- 100 meters deep.","opts":["out","under","from","among"],"ans":"B","xp":"Giới từ. 'under 100 meters deep' = ở độ sâu 100 mét dưới nước → (B) under. (A) out, (C) from, (D) among 'giữa (nhiều thứ)' không hợp.\nDịch: Chiếc đồng hồ đeo tay dành cho người mê thể thao mạo hiểm có khả năng chống nước, ngay cả ở độ sâu 100 mét dưới nước."},{"n":120,"q":"Your parking permit should be ------- whenever you enter the reserved parking area.","opts":["verify","verified","verification","verifying"],"ans":"B","xp":"Thể bị động. Chủ ngữ 'Your parking permit' (giấy phép đỗ xe) được kiểm tra → should be + V3 (B) verified. (A) động từ nguyên thể, (C) danh từ, (D) V-ing (chủ động) sai nghĩa.\nDịch: Giấy phép đỗ xe của bạn phải được kiểm tra mỗi khi vào khu đỗ xe dành riêng."},{"n":121,"q":"Please note that all vending machines throughout this building require ------- change.","opts":["exact","exacted","exactly","exactness"],"ans":"A","xp":"Từ loại. Trước danh từ 'change' (tiền lẻ) cần tính từ → (A) exact; exact change = tiền vừa đúng số, không cần thối lại. (B) V3, (C) trạng từ, (D) danh từ.\nDịch: Xin lưu ý rằng mọi máy bán hàng tự động trong tòa nhà đều yêu cầu trả tiền vừa đúng."},{"n":122,"q":"The sales manager will hold a department luncheon in ------- of meeting their quarterly sales quota early.","opts":["deliverance","celebration","perspective","competence"],"ans":"B","xp":"Từ vựng. in celebration of = để ăn mừng → (B). (A) deliverance 'sự giải thoát', (C) perspective 'quan điểm', (D) competence 'năng lực' không hợp.\nDịch: Trưởng phòng kinh doanh sẽ tổ chức bữa trưa cho phòng để ăn mừng việc đạt chỉ tiêu bán hàng quý sớm."},{"n":123,"q":"Be sure to submit expense reports by the 20th each month ------- you can be reimbursed without delay.","opts":["due to","as long as","so that","in addition"],"ans":"C","xp":"Liên từ. Sau chỗ trống là mệnh đề 'you can be reimbursed...' chỉ mục đích → (C) so that 'để'. (A) due to là giới từ, (B) as long as 'miễn là' không hợp nghĩa, (D) in addition là trạng từ.\nDịch: Hãy nhớ nộp báo cáo chi phí trước ngày 20 hằng tháng để được hoàn tiền không chậm trễ."},{"n":124,"q":"Danielle's Outlet trains its employees in case of emergencies they might ------- on the job.","opts":["depend","conclude","evaluate","encounter"],"ans":"D","xp":"Từ vựng. encounter emergencies = gặp phải tình huống khẩn cấp → (D). (A) depend (cần 'on'), (B) conclude 'kết luận', (C) evaluate 'đánh giá' không hợp.\nDịch: Danielle's Outlet đào tạo nhân viên để xử lý các tình huống khẩn cấp họ có thể gặp trong công việc."},{"n":125,"q":"Ms. Hawthorn was called to pick up her badge that -------.","opts":["misplace","misplaces","was misplaced","misplaced"],"ans":"C","xp":"Thể bị động. Chủ ngữ của mệnh đề quan hệ là 'that' = 'her badge' (thẻ tên) → thẻ 'bị để thất lạc', và không có tân ngữ sau chỗ trống → bị động (C) was misplaced. (A)(B)(D) là dạng chủ động.\nDịch: Bà Hawthorn được gọi đến lấy thẻ tên bị để quên của mình."},{"n":126,"q":"The supply manager's responsibility is to make sure that all office goods are ------- used.","opts":["productively","production","produce","productive"],"ans":"A","xp":"Từ loại. Chỗ trống bổ nghĩa cho V3 'used' trong 'are ------- used' → trạng từ (A) productively 'một cách hiệu quả'. (B) danh từ, (C) động từ, (D) tính từ.\nDịch: Trách nhiệm của quản lý vật tư là đảm bảo mọi đồ dùng văn phòng được sử dụng hiệu quả."},{"n":127,"q":"Even though German Tech Company increased the prices of its laundry machines, customers ------- think of them as the most affordable ones.","opts":["still","quite","much","ago"],"ans":"A","xp":"Trạng từ. 'Dù tăng giá, khách hàng vẫn nghĩ...' → (A) still 'vẫn'. (B) quite 'khá', (C) much 'nhiều', (D) ago 'trước đây' không đứng trước động từ.\nDịch: Dù German Tech Company đã tăng giá máy giặt, khách hàng vẫn xem đây là loại máy có giá phải chăng nhất."},{"n":128,"q":"------- you haven't earned the required credits for graduation, you need to meet your academic supervisor.","opts":["Meanwhile","Shortly","Regarding","If"],"ans":"D","xp":"Liên từ. Câu có hai mệnh đề, chỗ trống đứng đầu cần liên từ → (D) If 'nếu'. (A) Meanwhile, (B) Shortly là trạng từ, (C) Regarding là giới từ.\nDịch: Nếu bạn chưa đủ tín chỉ để tốt nghiệp, bạn cần gặp cố vấn học tập."},{"n":129,"q":"This coming Friday evening is ------- Ms. Min's retirement party is scheduled to be held.","opts":["it’s","who","on","when"],"ans":"D","xp":"Trạng từ quan hệ. Sau chỗ trống là mệnh đề đầy đủ, chỉ thời điểm 'Friday evening' → (D) when. (A) it's thừa chủ ngữ-động từ, (B) who dùng cho người, (C) on là giới từ.\nDịch: Tối thứ Sáu tới là lúc tổ chức tiệc chia tay nghỉ hưu của bà Min."},{"n":130,"q":"Please avoid contacting anyone on leave unless an issue needs ------- attention.","opts":["immediate","insufficient","careless","customary"],"ans":"A","xp":"Từ vựng. need immediate attention = cần xử lý ngay → (A). (B) insufficient 'không đủ', (C) careless 'bất cẩn', (D) customary 'theo thông lệ' không hợp.\nDịch: Vui lòng tránh liên lạc với người đang nghỉ phép trừ khi có việc cần xử lý ngay."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following notice.","passage":"<h3>NOTICE TO ALL EMPLOYEES</h3><p>You are entering an active area of the production floor. For your <span class=\"blank\" data-n=\"131\">-------</span>, you must wear protective gear in this area at all times. This includes hard hats, gloves, and eyewear. <span class=\"blank\" data-n=\"132\">-------</span> to comply with the regulations could result in personal injury as well as a fine for the company. If you do not have the necessary gear, please <span class=\"blank\" data-n=\"133\">-------</span> with your immediate supervisor. You should also check the condition of your gear to try to find damage. <span class=\"blank\" data-n=\"134\">-------</span> Thank you for your cooperation.</p>","vi":"THÔNG BÁO GỬI TOÀN THỂ NHÂN VIÊN\n\nBạn đang vào khu vực sản xuất đang hoạt động. Vì sự an toàn của bạn, bạn phải luôn mang đồ bảo hộ trong khu vực này, gồm mũ bảo hộ, găng tay và kính bảo hộ. Việc không tuân thủ quy định có thể gây chấn thương cho bản thân và khiến công ty bị phạt. Nếu bạn không có đồ bảo hộ cần thiết, vui lòng trao đổi với cấp trên trực tiếp. Bạn cũng nên kiểm tra tình trạng đồ bảo hộ để phát hiện hư hỏng. Nếu có hư hỏng, cần thay thế càng sớm càng tốt. Cảm ơn sự hợp tác của bạn.","qs":[{"n":131,"opts":["safer","safety","safely","safe"],"ans":"B","xp":"Từ loại. Sau tính từ sở hữu 'your' cần danh từ → (B) safety 'sự an toàn'; For your safety = vì sự an toàn của bạn. (A)(D) tính từ, (C) trạng từ."},{"n":132,"opts":["Closure","Precaution","Disruption","Failure"],"ans":"D","xp":"Từ vựng. failure to V = việc không làm gì → 'Failure to comply with the regulations' = việc không tuân thủ quy định → (D). (A) Closure 'đóng cửa', (B) Precaution 'phòng ngừa', (C) Disruption 'gián đoạn' không hợp."},{"n":133,"opts":["speak","speaks","spoken","speaking"],"ans":"A","xp":"Câu mệnh lệnh. Sau 'please' dùng động từ nguyên thể → (A) speak; speak with = nói chuyện với. (B) chia ngôi 3, (C) V3, (D) V-ing."},{"n":134,"opts":["As expected, it held up well in the preliminary tests.","Each employee received one upon starting work.","If you do, it should be replaced as soon as possible.","There is extra time available if you need it."],"ans":"C","xp":"Điền câu. Câu trước: 'check the condition of your gear to try to find damage' → câu tiếp: 'Nếu bạn phát hiện (hư hỏng), cần thay ngay' → (C); 'If you do' = If you find damage. (B) mâu thuẫn với câu 'If you do not have the necessary gear'."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Ivy Acuna &lt;acunai@woodlandinteriors.com&gt;</p><p><b>From:</b> Frank Dotson &lt;dotsonf@woodlandinteriors.com&gt;</p><p><b>Date:</b> April 6</p><p><b>Subject:</b> Our meeting</p></div><p>I would like <span class=\"blank\" data-n=\"135\">-------</span> for missing our scheduled meeting this morning. I know that you are busy, and I'm sure it was a great inconvenience to you. <span class=\"blank\" data-n=\"136\">-------</span>, my return flight from Vancouver was delayed, so I got back into town much later than I had originally expected. We still need to go over the interior design for the property on Carter Street. <span class=\"blank\" data-n=\"137\">-------</span> I can drop by your office tomorrow afternoon around 3. I hope you find that <span class=\"blank\" data-n=\"138\">-------</span>. If not, we can find another time that works.</p><p>Sincerely,<br>Frank Dotson</p>","vi":"Người nhận: Ivy Acuna | Người gửi: Frank Dotson | Ngày: 6/4 | Chủ đề: Cuộc họp của chúng ta\n\nTôi muốn xin lỗi vì đã lỡ cuộc họp đã lên lịch sáng nay. Tôi biết chị bận và chắc việc này đã gây nhiều bất tiện cho chị. Không may, chuyến bay về từ Vancouver của tôi bị trễ, nên tôi về đến thành phố muộn hơn nhiều so với dự kiến. Chúng ta vẫn cần xem lại thiết kế nội thất cho căn nhà trên phố Carter. Việc này gặp trực tiếp sẽ dễ hơn nhiều. Tôi có thể ghé văn phòng chị khoảng 3 giờ chiều mai. Mong là chị thấy giờ đó được. Nếu không, chúng ta có thể tìm giờ khác phù hợp.\n\nTrân trọng,\nFrank Dotson","qs":[{"n":135,"opts":["being apologized","apologizing","apologized","to apologize"],"ans":"D","xp":"Động từ. would like + to V → (D) to apologize 'muốn xin lỗi'. (A)(B)(C) không đi sau 'would like'."},{"n":136,"opts":["Namely","Moreover","Unfortunately","Nonetheless"],"ans":"C","xp":"Trạng từ nối. Câu sau kể chuyện không may: 'chuyến bay bị trễ' → (C) Unfortunately 'Không may là'. (A) Namely 'cụ thể là', (B) Moreover 'hơn nữa', (D) Nonetheless 'tuy nhiên' không hợp."},{"n":137,"opts":["The attachment he sent did not open.","You should contact the Vancouver office.","This will be much easier to do in person.","Our project received the highest rating."],"ans":"C","xp":"Điền câu. Trước: 'We still need to go over the interior design'; sau: 'I can drop by your office tomorrow' → câu giữa giải thích vì sao muốn gặp: 'gặp trực tiếp sẽ dễ hơn' → (C)."},{"n":138,"opts":["accepted","acceptable","acceptably","acceptance"],"ans":"B","xp":"Từ loại. Cấu trúc find + O + tính từ: 'find that acceptable' = thấy (giờ đó) chấp nhận được → (B). (A) V3 không hợp nghĩa ở đây, (C) trạng từ, (D) danh từ."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following advertisement.","passage":"<h3>Volunteers Wanted:</h3><p>Helpful Hearts is currently seeking volunteers for its programs to help the elderly. Tasks range <span class=\"blank\" data-n=\"139\">-------</span> visiting people in their homes and assisting with household chores to providing rides to appointments. You're sure to find something that suits your schedule and interests. By volunteering with Helpful Hearts, you can truly make a <span class=\"blank\" data-n=\"140\">-------</span> in another person's life. <span class=\"blank\" data-n=\"141\">-------</span> Even just two hours a week is sufficient. If this sounds appealing to you, why not give it a try? You can visit our Web site at www.helpfulhearts1.org to learn more about us and <span class=\"blank\" data-n=\"142\">-------</span> testimonials from our volunteers and participants.</p>","vi":"Tuyển tình nguyện viên:\n\nHelpful Hearts đang tìm tình nguyện viên cho các chương trình giúp đỡ người cao tuổi. Công việc gồm từ thăm người già tại nhà và giúp việc nhà đến đưa đón họ đi khám. Bạn chắc chắn sẽ tìm được việc hợp với lịch và sở thích của mình. Khi làm tình nguyện cùng Helpful Hearts, bạn thật sự có thể tạo nên khác biệt trong cuộc sống của người khác. Chúng tôi không đòi hỏi bạn dành nhiều thời gian. Chỉ hai tiếng mỗi tuần cũng đủ. Nếu thấy hấp dẫn, sao không thử một lần? Bạn có thể vào trang web www.helpfulhearts1.org để tìm hiểu thêm về chúng tôi và xem cảm nhận của các tình nguyện viên và người tham gia.","qs":[{"n":139,"opts":["from","toward","through","within"],"ans":"A","xp":"Giới từ. Cấu trúc range from A to B = gồm từ A đến B; phía sau có 'to providing rides' → (A) from."},{"n":140,"opts":["comment","difference","choice","prediction"],"ans":"B","xp":"Từ vựng. make a difference in someone's life = tạo nên khác biệt/thay đổi tốt cho cuộc sống của ai → (B). (A) make a comment 'bình luận', (C) make a choice 'lựa chọn', (D) make a prediction 'dự đoán' không hợp."},{"n":141,"opts":["There are various group sizes working for us.","We don't ask for a large time commitment.","Training is provided to newcomers if requested.","You do not need special skills to volunteer."],"ans":"B","xp":"Điền câu. Câu sau: 'Even just two hours a week is sufficient' (chỉ 2 tiếng/tuần là đủ) → câu trước phải nói về thời gian: 'Chúng tôi không đòi hỏi bạn dành nhiều thời gian' → (B)."},{"n":142,"opts":["are browsed","browsed","browsing","browse"],"ans":"D","xp":"Cấu trúc song song. 'to learn more about us and ------- testimonials' → nối với 'learn' sau 'to' nên dùng động từ nguyên thể (D) browse 'xem'. (A) bị động, (B) V3, (C) V-ing không song song."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Quinn Gleason &lt;gleasonq@camdencslting.com&gt;</p><p><b>From:</b> Christina Cruz &lt;cruzc@camdencslting.com&gt;</p><p><b>Date:</b> December 17</p><p><b>Subject:</b> Workshop</p></div><p>I've <span class=\"blank\" data-n=\"143\">-------</span> the information I gathered from the staff members who took your Organizational Skills Workshop last week. <span class=\"blank\" data-n=\"144\">-------</span> For example, the majority of attendees said they would like to take one of your workshops in the future, and all of them said they found the information to be helpful. The main complaint was about the equipment you used to show the videos. People said they could <span class=\"blank\" data-n=\"145\">-------</span> hear the audio track. Because of this problem, they couldn't understand <span class=\"blank\" data-n=\"146\">-------</span> was being said. Let's keep this issue in mind for next time.</p><p>Sincerely,<br>Christina</p>","vi":"Người nhận: Quinn Gleason | Người gửi: Christina Cruz | Ngày: 17/12 | Chủ đề: Hội thảo\n\nTôi đã phân tích thông tin thu thập từ các nhân viên đã tham gia hội thảo Kỹ năng Tổ chức của anh tuần trước. Nhìn chung, phản hồi rất tích cực. Ví dụ, phần lớn người tham dự nói họ muốn học một hội thảo khác của anh trong tương lai, và tất cả đều thấy thông tin hữu ích. Phàn nàn chính là về thiết bị anh dùng để chiếu video. Mọi người nói họ hầu như không nghe được âm thanh. Vì vậy, họ không hiểu được nội dung đang nói. Lần sau chúng ta hãy lưu ý vấn đề này.\n\nTrân trọng,\nChristina","qs":[{"n":143,"opts":["authorized","emphasized","strategized","analyzed"],"ans":"D","xp":"Từ vựng. analyze the information = phân tích thông tin thu thập được → (D). (A) authorized 'cho phép', (B) emphasized 'nhấn mạnh', (C) strategized 'lập chiến lược' không hợp."},{"n":144,"opts":["Sadly, attendance was lower than ever.","I am happy to prepare the materials for you.","Overall, the feedback was very positive.","This will be the last session of the year."],"ans":"C","xp":"Điền câu. Câu sau bắt đầu 'For example, ... would like to take ... found the information to be helpful' là ví dụ cho nhận xét tích cực → (C) 'Nhìn chung phản hồi rất tích cực'."},{"n":145,"opts":["bare","bared","barely","barer"],"ans":"C","xp":"Từ loại. Giữa 'could' và động từ 'hear' cần trạng từ → (C) barely 'hầu như không'. (A)(D) tính từ, (B) động từ quá khứ."},{"n":146,"opts":["what","that","which","such"],"ans":"A","xp":"Đại từ quan hệ. 'understand ------- was being said': chỗ trống vừa làm tân ngữ cho 'understand' vừa làm chủ ngữ cho 'was being said' → (A) what 'điều mà'. (B)(C) cần danh từ đứng trước, (D) such không làm chủ ngữ mệnh đề."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following text message.","passages":["<div class=\"hdr\"><p><b>From:</b> Chelsea Ware, Thursday, 10 March, 1:42 P.M.</p></div><p>Vicky, I'm at Gulfport Diner to respond to a maintenance call. Initially they wanted us to fix their air conditioning, so I brought the tools for that. However, they also asked me to work on their boiler. I don't have what I need for that. Could you do me a favor and bring me the other tool kit from our shop? I'll work on the air conditioning unit in the meantime. Then I can finish all the work here today. Thanks for your help.</p>"],"vi":"Từ: Chelsea Ware, thứ Năm, 10 tháng 3, 1:42 chiều\n\nVicky, tôi đang ở quán Gulfport Diner để xử lý yêu cầu bảo trì. Ban đầu họ muốn chúng ta sửa điều hòa nên tôi mang đồ nghề cho việc đó. Nhưng họ còn nhờ tôi sửa nồi hơi. Tôi không có đồ cần thiết cho việc này. Chị có thể giúp tôi mang bộ đồ nghề kia từ cửa hàng đến không? Trong lúc chờ, tôi sẽ sửa điều hòa. Như vậy hôm nay tôi có thể làm xong mọi việc ở đây. Cảm ơn chị đã giúp.","qs":[{"n":147,"q":"What does Ms. Ware say is a problem?","qvi":"Cô Ware nói vấn đề là gì?","opts":["She is unfamiliar with a system.","She cannot find a location.","She has too much work.","She received another request on a site."],"ans":"D","xp":"'Initially they wanted us to fix their air conditioning... However, they also asked me to work on their boiler. I don't have what I need for that' → tại chỗ làm, cô nhận thêm một yêu cầu khác → (D).\n(A) không quen hệ thống, (B) không tìm được địa điểm, (C) quá nhiều việc: không được nhắc."},{"n":148,"q":"What did Ms. Ware ask Vicky to do?","qvi":"Cô Ware nhờ Vicky làm gì?","opts":["Give some instructions","Order a replacement part","Bring some tools","Attend a weekly meeting"],"ans":"C","xp":"'Could you... bring me the other tool kit from our shop?' → mang đồ nghề → (C)."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following receipt.","passages":["<h3>Tokyo Airport</h3><h4>Private Resting Area</h4><table><tr><td>Customer Name:</td><td>Yun Zhen Li</td></tr><tr><td>Room Type:</td><td>Single Bed, Shower</td></tr><tr><td>First Hour:</td><td>1,500¥ (500¥ / 30 min. after)</td></tr><tr><td>Check-in Time:</td><td>May 16, 0620</td></tr><tr><td>Check-out Time:</td><td>May 16, 0850</td></tr><tr><td>Total Charge:</td><td>2,700¥*</td></tr></table><p>*(Air VIP Member Discount Applied)</p><p>Thank you for staying with us! Visit us again next time!</p>"],"vi":"Sân bay Tokyo – Khu nghỉ riêng\n\nTên khách: Yun Zhen Li | Loại phòng: giường đơn, có vòi sen | Giờ đầu: 1.500 yên (sau đó 500 yên / 30 phút) | Nhận phòng: 16/5, 06:20 | Trả phòng: 16/5, 08:50 | Tổng tiền: 2.700 yên* (*Đã áp dụng giảm giá hội viên Air VIP)\n\nCảm ơn quý khách đã nghỉ tại đây! Hẹn gặp lại lần sau!","qs":[{"n":149,"q":"What did Mr. Li do on May 16?","qvi":"Ngày 16/5 ông Li đã làm gì?","opts":["Used an airport facility","Stayed in a hotel","Departed from Tokyo","Cancelled a membership"],"ans":"A","xp":"Hóa đơn của 'Tokyo Airport – Private Resting Area' (khu nghỉ riêng ở sân bay), nhận phòng 06:20 trả 08:50 ngày 16/5 → ông dùng một tiện ích của sân bay → (A). (B) không phải khách sạn; (C) không biết ông có bay đi từ Tokyo không."},{"n":150,"q":"What is suggested about Mr. Li?","qvi":"Có thể suy ra điều gì về ông Li?","opts":["He got a first class flight upgrade.","He is an Air VIP member.","He booked a shuttle to downtown.","He wanted to extend his stay."],"ans":"B","xp":"'Total Charge: 2,700¥* — *(Air VIP Member Discount Applied)' → ông được giảm giá hội viên → ông là hội viên Air VIP → (B)."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text message chain.","passages":["<div class=\"msg\"><p><b>Jacob Perkins [1:03 P.M.]</b></p><p>Are you at the Waycross Convention Center yet? I know you were worried about missing the bus.</p></div><div class=\"msg\"><p><b>Sarama Bisrat [1:06 P.M.]</b></p><p>Fortunately, I was able to catch it. I should be at the center soon. We just passed the Crystal Mall.</p></div><div class=\"msg\"><p><b>Jacob Perkins [1:07 P.M.]</b></p><p>Great. Are you expecting any packages while you're away from the office?</p></div><div class=\"msg\"><p><b>Sarama Bisrat [1:08 P.M.]</b></p><p>Just one from Braxton Manufacturing. It doesn't contain anything time-sensitive.</p></div><div class=\"msg\"><p><b>Jacob Perkins [1:09 P.M.]</b></p><p>All right. Usually I open packages for people when they're gone. But I'll just leave it on your desk.</p></div><div class=\"msg\"><p><b>Sarama Bisrat [1:10 P.M.]</b></p><p>That seems best to me.</p></div>"],"vi":"Jacob Perkins (1:03): Chị đến Trung tâm Hội nghị Waycross chưa? Tôi biết chị lo bị lỡ xe buýt.\nSarama Bisrat (1:06): May là tôi kịp bắt xe. Chắc tôi sắp đến trung tâm rồi. Xe vừa đi qua Crystal Mall.\nJacob Perkins (1:07): Tốt quá. Trong lúc chị đi vắng, chị có đợi bưu kiện nào không?\nSarama Bisrat (1:08): Chỉ có một gói của Braxton Manufacturing. Trong đó không có gì gấp.\nJacob Perkins (1:09): Được. Thường thì khi mọi người đi vắng, tôi mở bưu kiện giúp họ. Nhưng tôi sẽ để nguyên gói này trên bàn chị.\nSarama Bisrat (1:10): Vậy là tốt nhất.","qs":[{"n":151,"q":"Where most likely is Ms. Bisrat when she sends the messages?","qvi":"Khi nhắn tin, cô Bisrat nhiều khả năng đang ở đâu?","opts":["In an office","At a conference venue","On a bus","At a shopping mall"],"ans":"C","xp":"'I was able to catch it (the bus). I should be at the center soon. We just passed the Crystal Mall' → cô đang trên xe buýt → (C). (B) chưa đến trung tâm, (D) chỉ vừa đi qua trung tâm thương mại."},{"n":152,"q":"At 1:10 P.M., what does Ms. Bisrat mean when she writes, \"That seems best to me\"?","qvi":"Lúc 1:10, cô Bisrat có ý gì khi viết \"Vậy là tốt nhất\"?","opts":["She plans to come back to the office to complete an urgent task.","She does not want Mr. Perkins to open a package.","She thinks it is a good idea to contact Braxton Manufacturing.","She wants a delivery to be stored in Mr. Perkins' office."],"ans":"B","xp":"Ông Perkins nói thường mở bưu kiện giúp, 'But I'll just leave it on your desk' (để nguyên không mở); cô đồng ý → cô không muốn ông mở gói hàng → (B). (D) gói để trên bàn cô, không phải ở phòng ông."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following information.","passages":["<h3>Timberland Marketing Expense Reimbursement Policy</h3><ul><li>All reimbursement requests must be made via company form AC232.</li><li>Acceptable reimbursements include meals for clients, business travel, office supplies, and others approved in advance.</li><li>Original receipts must be included whenever possible.</li><li>Reimbursements will be deposited on the first of the following month, provided that the request is submitted within the first two weeks of the current month.</li></ul><p>*Each team has its own budget. Please check with your team leader before making any purchases or charges that you expect to be reimbursed for.*</p>"],"vi":"Chính sách hoàn trả chi phí của Timberland Marketing\n\n- Mọi yêu cầu hoàn tiền phải làm bằng mẫu đơn AC232 của công ty.\n- Các khoản được hoàn gồm: bữa ăn với khách hàng, đi công tác, văn phòng phẩm và các khoản khác được duyệt trước.\n- Kèm hóa đơn gốc bất cứ khi nào có thể.\n- Tiền hoàn sẽ được chuyển vào ngày 1 tháng sau, với điều kiện yêu cầu được nộp trong hai tuần đầu của tháng hiện tại.\n\nMỗi nhóm có ngân sách riêng. Vui lòng hỏi trưởng nhóm trước khi mua hay chi bất kỳ khoản nào mà bạn muốn được hoàn tiền.","qs":[{"n":153,"q":"What does every reimbursement request require?","qvi":"Mọi yêu cầu hoàn tiền đều cần gì?","opts":["An official form","A budget report","A team leader's signature","A travel itinerary"],"ans":"A","xp":"'All reimbursement requests must be made via company form AC232' → (A). (C) chỉ nói hỏi trưởng nhóm trước, không nói cần chữ ký."},{"n":154,"q":"What is mentioned about Timberland Marketing?","qvi":"Điều gì được nhắc đến về Timberland Marketing?","opts":["It reimburses expenses after two weeks.","It pays its employees every other week.","It assigns individual team budgets.","It issues company credit cards to employees."],"ans":"C","xp":"'Each team has its own budget' → mỗi nhóm có ngân sách riêng → (C). (A) sai: tiền hoàn chuyển vào ngày 1 tháng sau."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following invoice.","passages":["<h3>Jacobson's Warehouse</h3><p>Victoria Court<br>Standish, ME 04084</p><table><tr><th>Billing Information</th><th>Shipping Information</th></tr><tr><td>Debra Collins, 73 Hawthorne Lane, Standish, ME 04084</td><td>SAME</td></tr></table><p><b>Expected Arrival:</b> 7 April (after 4 p.m.)</p><table><tr><th>Code</th><th>Item</th><th>Price</th></tr><tr><td>*1672-0938</td><td>Dehumidifier</td><td>$69.00</td></tr><tr><td>8704-9225</td><td>Electric Fan</td><td>$24.00</td></tr><tr><td>7000-1643</td><td>Toaster (2-slot)</td><td>$16.00</td></tr><tr><td>2099-5815</td><td>Digital Clock</td><td>$8.00</td></tr><tr><td>0000-0000</td><td>Discount Coupon</td><td>-$15.00</td></tr></table><p>*Due to its large size, this item will be shipped separately. Please allow an extra 1-2 days for delivery.</p>"],"vi":"Jacobson's Warehouse – Victoria Court, Standish, ME 04084\n\nThông tin thanh toán: Debra Collins, 73 Hawthorne Lane, Standish | Thông tin giao hàng: giống như trên\nDự kiến giao: 7 tháng 4 (sau 4 giờ chiều)\n\nMã – Mặt hàng – Giá: *1672-0938 Máy hút ẩm 69 đô | 8704-9225 Quạt điện 24 đô | 7000-1643 Máy nướng bánh mì (2 khe) 16 đô | 2099-5815 Đồng hồ điện tử 8 đô | Phiếu giảm giá −15 đô\n\n*Do kích thước lớn, mặt hàng này sẽ được gửi riêng. Vui lòng chờ thêm 1–2 ngày.","qs":[{"n":155,"q":"What kind of business is Jacobson's Warehouse?","qvi":"Jacobson's Warehouse là loại cơ sở kinh doanh nào?","opts":["A restaurant","A courier service","An appliance store","A furniture manufacturer"],"ans":"C","xp":"Hóa đơn gồm máy hút ẩm, quạt điện, máy nướng bánh mì, đồng hồ điện tử → cửa hàng đồ gia dụng → (C)."},{"n":156,"q":"What is scheduled to happen on 7 April?","qvi":"Ngày 7 tháng 4 dự kiến có việc gì?","opts":["An inventory will be checked.","A discount coupon will expire.","A partial order will be delivered.","An appliance will be assembled."],"ans":"C","xp":"'Expected Arrival: 7 April'; nhưng máy hút ẩm (*) 'will be shipped separately... extra 1-2 days' → ngày 7/4 chỉ giao một phần đơn hàng → (C)."},{"n":157,"q":"What is indicated about the dehumidifier?","qvi":"Điều gì được cho biết về máy hút ẩm?","opts":["It will arrive at a later date.","It ships directly from the factory.","It includes an extended warranty.","It is not eligible for a free delivery."],"ans":"A","xp":"Máy hút ẩm có dấu *: 'this item will be shipped separately. Please allow an extra 1-2 days' → đến muộn hơn → (A)."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following article.","passages":["<h3>International Business Gazette: Business Briefings, November 9</h3><p>By Ansel Routhier</p><p>The long-expected union of Tanty Technologies and Invert Solutions has been confirmed following a meeting of the shareholders late last night. Newly appointed CEO Daniel Hardwick said that the arrangement would allow the newly-formed corporation, which will trade under the name \"Tanty Solutions,\" to access the important Association of South East Asian Nations (ASEAN) region. <span class=\"pos\">[1]</span></p><p>While many industry observers predicted the move as long ago as last year, negotiations had temporarily stalled due to copyright issues regarding Invert Solutions' banking software. <span class=\"pos\">[2]</span> With the court case being resolved in favor of Invert Solutions last month, the final barrier to the partnership was removed. <span class=\"pos\">[3]</span></p><p>The same observers have predicted that revenues will rise immediately for the new corporation, with the sale of Tanty Technologies' robust financial prediction computer programs to Invert Solutions' Asian customer base. Additionally, many European and American customers of Tanty Technologies have expressed strong interest in the flexibility of Invert Solutions' products. <span class=\"pos\">[4]</span></p><p>The rest of the industry is watching carefully to see whether the transition will solidify a market giant or leave room for start-ups to gain ground.</p>"],"vi":"Báo Kinh doanh Quốc tế: Tin vắn kinh doanh, ngày 9 tháng 11 – Ansel Routhier\n\nViệc sáp nhập được chờ đợi từ lâu giữa Tanty Technologies và Invert Solutions đã được xác nhận sau cuộc họp cổ đông tối qua. Tân giám đốc điều hành Daniel Hardwick cho biết thỏa thuận này sẽ giúp tập đoàn mới, hoạt động dưới tên \"Tanty Solutions\", tiếp cận khu vực quan trọng ASEAN (Hiệp hội các quốc gia Đông Nam Á).\n\nDù nhiều nhà quan sát trong ngành đã dự đoán việc này từ năm ngoái, đàm phán từng tạm dừng vì vấn đề bản quyền phần mềm ngân hàng của Invert Solutions. Khi vụ kiện được phân xử có lợi cho Invert Solutions vào tháng trước, rào cản cuối cùng cho sự hợp tác đã được gỡ bỏ.\n\nCác nhà quan sát cũng dự đoán doanh thu của tập đoàn mới sẽ tăng ngay nhờ bán các chương trình máy tính dự báo tài chính mạnh mẽ của Tanty Technologies cho khách hàng châu Á của Invert Solutions. Ngoài ra, nhiều khách hàng châu Âu và Mỹ của Tanty Technologies rất quan tâm đến tính linh hoạt của sản phẩm Invert Solutions. Những yếu tố này là ví dụ cho thấy thế mạnh của mỗi công ty sẽ thúc đẩy thành công.\n\nPhần còn lại của ngành đang theo dõi sát xem sự chuyển đổi này sẽ tạo nên một gã khổng lồ trên thị trường hay để lại chỗ cho các công ty khởi nghiệp vươn lên.","qs":[{"n":158,"q":"Why was the article written?","qvi":"Bài báo được viết nhằm mục đích gì?","opts":["To announce a corporate buyout","To report on a business merger","To describe a shareholder policy","To outline a recent software trend"],"ans":"B","xp":"'The long-expected union of Tanty Technologies and Invert Solutions has been confirmed' → hai công ty hợp nhất thành 'Tanty Solutions' → tin về sáp nhập → (B). (A) buyout là một công ty mua lại công ty kia, không phải hợp nhất."},{"n":159,"q":"What kind of company most likely is Invert Solutions?","qvi":"Invert Solutions nhiều khả năng là loại công ty nào?","opts":["A corporate consulting firm","A software developer","A computer manufacturer","An Internet security company"],"ans":"B","xp":"'copyright issues regarding Invert Solutions' banking software' → công ty làm phần mềm → (B)."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"These factors are examples of how the strengths of each company will be drivers of success.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Những yếu tố này là ví dụ cho thấy thế mạnh của mỗi công ty sẽ thúc đẩy thành công.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"'These factors' phải chỉ các yếu tố vừa nêu về thế mạnh của cả hai công ty: phần mềm dự báo tài chính của Tanty bán cho khách châu Á của Invert, khách châu Âu/Mỹ của Tanty quan tâm sản phẩm Invert → đặt sau đoạn này, vị trí [4] → (D)."}]},{"ns":[161,164],"head":"Questions 161-164 refer to the following Web site.","passages":["<h3>National Census Bureau</h3><p>The national census is conducted annually to get a general understanding of the various demographics in our country. The questions cover a broad spectrum including age, gender, race, income, family size, marital status, and other topics. It is important that people answer the questions honestly and to the best of their ability and knowledge. Although it is not mandatory, we appreciate those who respond to our questionnaire.</p><p>Census data is helpful to many kinds of social and scientific research and has been cited in many publications. If you are interested in using any of the statistics that our bureau has collected, you must first obtain permission. Please contact us at admin@ncb.gov and be sure to include your name, the intended use of our data, and the name of the publication you intend to use it in. Most requests are responded to within two business days. There is no charge for using census data once permission has been granted.</p>"],"vi":"Cục Điều tra Dân số Quốc gia\n\nCuộc điều tra dân số quốc gia được tiến hành hằng năm để có hiểu biết cơ bản về các nhóm dân cư khác nhau trong nước. Câu hỏi bao gồm nhiều mảng như tuổi, giới tính, chủng tộc, thu nhập, quy mô gia đình, tình trạng hôn nhân và các chủ đề khác. Điều quan trọng là mọi người trả lời trung thực và hết khả năng, hiểu biết của mình. Dù không bắt buộc, chúng tôi trân trọng những ai trả lời bảng câu hỏi.\n\nDữ liệu điều tra dân số hữu ích cho nhiều loại nghiên cứu xã hội và khoa học, và đã được trích dẫn trong nhiều ấn phẩm. Nếu bạn muốn dùng số liệu thống kê do cục thu thập, bạn phải xin phép trước. Vui lòng liên hệ admin@ncb.gov, ghi rõ tên, mục đích sử dụng dữ liệu và tên ấn phẩm bạn định đăng. Phần lớn yêu cầu được trả lời trong hai ngày làm việc. Không mất phí sử dụng dữ liệu sau khi được cấp phép.","qs":[{"n":161,"q":"The word \"general\" in paragraph 1, line 1, is closest in meaning to","qvi":"Từ \"general\" ở đoạn 1, dòng 1 gần nghĩa nhất với","opts":["organized","basic","leading","simple"],"ans":"B","xp":"'to get a general understanding' = có hiểu biết chung, cơ bản → (B) basic. (D) simple 'đơn giản' không hợp với 'understanding'."},{"n":162,"q":"What is NOT indicated about the census participants?","qvi":"Điều gì KHÔNG được nói về người tham gia điều tra dân số?","opts":["They should all have U.S. citizenship.","They are asked to be honest.","They are willing to take a survey.","They belong to varied groups."],"ans":"A","xp":"(B) 'answer the questions honestly'; (C) 'Although it is not mandatory, we appreciate those who respond' → người trả lời là tự nguyện; (D) 'the various demographics'. Không có câu nào nói phải có quốc tịch Mỹ → (A)."},{"n":163,"q":"What is stated about the National Census Bureau?","qvi":"Điều gì được nêu về Cục Điều tra Dân số Quốc gia?","opts":["It is funded by the government.","It employs a large research team.","It charges a fee for using its data.","It has supplied data to multiple publications."],"ans":"D","xp":"'has been cited in many publications' → dữ liệu đã được dùng trong nhiều ấn phẩm → (D). (C) sai: 'There is no charge'."},{"n":164,"q":"How can one get permission to cite collected data?","qvi":"Làm thế nào để được phép trích dẫn dữ liệu?","opts":["By conducting research","By paying a small fee","By sending a request by e-mail","By filling out a form"],"ans":"C","xp":"'you must first obtain permission. Please contact us at admin@ncb.gov' → gửi yêu cầu qua e-mail → (C)."}]},{"ns":[165,167],"head":"Questions 165-167 refer to the following article.","passages":["<p>SANTEE, CA (3 NOVEMBER) — Finley Foods, a major snack producer, has announced a special contest. First, people will be asked to submit their ideas for a new potato chip flavor. The company will select five flavors and begin selling them in small sample pack sizes. Then, after one month, it will hold an online poll to determine which flavors should stay as a permanent addition to the brand. The first place winner to submit the most popular new flavor will be offered a position as a senior flavor specialist at one of Finley Foods' production and packaging sites. All other top submissions will receive a cash bonus based on how well their flavor sold.</p>"],"vi":"SANTEE, CA (3/11) — Finley Foods, nhà sản xuất đồ ăn vặt lớn, đã công bố một cuộc thi đặc biệt. Trước tiên, mọi người sẽ gửi ý tưởng về một vị khoai tây chiên mới. Công ty sẽ chọn năm vị và bắt đầu bán dưới dạng gói dùng thử nhỏ. Sau một tháng, công ty sẽ tổ chức bình chọn trực tuyến để quyết định vị nào được giữ lại lâu dài trong thương hiệu. Người thắng giải nhất – người gửi vị mới được yêu thích nhất – sẽ được mời làm chuyên viên hương vị cấp cao tại một cơ sở sản xuất và đóng gói của Finley Foods. Những bài dự thi hàng đầu khác sẽ nhận tiền thưởng tùy theo vị của họ bán chạy đến đâu.","qs":[{"n":165,"q":"What is the main purpose of the article?","qvi":"Mục đích chính của bài báo là gì?","opts":["To advertise a job opening","To promote a snack-making brand","To publicize a competition","To announce a leadership change"],"ans":"C","xp":"'Finley Foods... has announced a special contest' và cả bài mô tả cách thi → giới thiệu cuộc thi → (C)."},{"n":166,"q":"Who will select the most popular flavor?","qvi":"Ai sẽ chọn vị được yêu thích nhất?","opts":["A CEO of Finley Foods","The people who cast votes","Representatives from Finley Foods","A group of chefs"],"ans":"B","xp":"'it will hold an online poll to determine which flavors should stay' → người bỏ phiếu quyết định → (B). (C) công ty chỉ chọn 5 vị ban đầu."},{"n":167,"q":"What is stated about the first place winner?","qvi":"Điều gì được nói về người thắng giải nhất?","opts":["The largest amount of cash will be awarded.","The local newspaper will feature the winner.","The winner will be invited to tour the factory.","An employment opportunity will be given."],"ans":"D","xp":"'will be offered a position as a senior flavor specialist' → được mời làm việc → (D). (A) tiền thưởng dành cho các bài khác."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Aruna Jadhav [9:03 A.M.]</b></p><p>Chris Edwards in the IT department has just confirmed that his team has successfully removed the virus that affected our computer network. We did lose some of our design files in the process, though, right?</p></div><div class=\"msg\"><p><b>Gustave Tanguay [9:04 A.M.]</b></p><p>That's correct. Unfortunately, we were late getting the newly created logo to Valmeyer Manufacturing because we only had an earlier version of the file backed up.</p></div><div class=\"msg\"><p><b>Camilla Calvacante [9:06 A.M.]</b></p><p>That's a shame.</p></div><div class=\"msg\"><p><b>Riley Eldershaw [9:07 A.M.]</b></p><p>Yeah, it could negatively affect our reputation. We have to be stricter about making employees back up their work.</p></div><div class=\"msg\"><p><b>Aruna Jadhav [9:08 A.M.]</b></p><p>I agree. All we can do now is provide a partial refund to the Valmeyer Manufacturing account by way of compensation. Has anyone done that yet?</p></div><div class=\"msg\"><p><b>Camilla Calvacante [9:10 A.M.]</b></p><p>I plan to do that today, but I wanted to know what amount would be appropriate. Valmeyer Manufacturing is a regular client, so I was thinking around $250.</p></div><div class=\"msg\"><p><b>Gustave Tanguay [9:11 A.M.]</b></p><p>That sounds reasonable. Aruna, do we have that?</p></div><div class=\"msg\"><p><b>Aruna Jadhav [9:12 A.M.]</b></p><p>Yes. There's enough in our corporate bank account to cover that.</p></div>"],"vi":"Aruna Jadhav (9:03): Chris Edwards ở phòng IT vừa xác nhận nhóm anh ấy đã diệt xong virus làm ảnh hưởng mạng máy tính của mình. Nhưng trong quá trình đó mình bị mất một số tệp thiết kế, phải không?\nGustave Tanguay (9:04): Đúng vậy. Tiếc là mình đã giao logo mới cho Valmeyer Manufacturing bị trễ vì chỉ có bản sao lưu của phiên bản cũ.\nCamilla Calvacante (9:06): Tiếc quá.\nRiley Eldershaw (9:07): Ừ, việc này có thể ảnh hưởng xấu đến uy tín của mình. Mình phải nghiêm khắc hơn trong việc bắt nhân viên sao lưu công việc.\nAruna Jadhav (9:08): Tôi đồng ý. Giờ mình chỉ có thể hoàn một phần tiền vào tài khoản của Valmeyer Manufacturing để bồi thường. Đã ai làm việc đó chưa?\nCamilla Calvacante (9:10): Tôi định làm hôm nay, nhưng muốn biết số tiền bao nhiêu là hợp lý. Valmeyer Manufacturing là khách quen, nên tôi nghĩ khoảng 250 đô.\nGustave Tanguay (9:11): Nghe hợp lý đấy. Aruna, mình có khoản đó không?\nAruna Jadhav (9:12): Có. Tài khoản ngân hàng công ty đủ tiền để chi khoản đó.","qs":[{"n":168,"q":"Where most likely do the writers work?","qvi":"Những người viết nhiều khả năng làm việc ở đâu?","opts":["At an accounting firm","At a manufacturing facility","At a computer retail store","At a graphic design firm"],"ans":"D","xp":"'we lost some of our design files'; 'getting the newly created logo to Valmeyer Manufacturing' → họ thiết kế logo cho khách → công ty thiết kế đồ họa → (D). (B) Valmeyer Manufacturing là khách hàng."},{"n":169,"q":"What problem is mentioned in the discussion?","qvi":"Vấn đề nào được nhắc đến?","opts":["A cost has increased.","An employee was absent.","A shipment was damaged.","A deadline was missed."],"ans":"D","xp":"'we were late getting the newly created logo to Valmeyer Manufacturing' → giao trễ hạn → (D)."},{"n":170,"q":"What will Ms. Calvacante most likely do later today?","qvi":"Hôm nay cô Calvacante nhiều khả năng sẽ làm gì?","opts":["Send a letter of apology to a customer","Lead a meeting for the staff members","Issue a refund to a client account","Update an online price list"],"ans":"C","xp":"Aruna hỏi đã ai hoàn tiền một phần cho Valmeyer chưa; Camilla: 'I plan to do that today' → (C)."},{"n":171,"q":"At 9:11 A.M., what does Mr. Tanguay mean when he writes, \"do we have that\"?","qvi":"Lúc 9:11, ông Tanguay có ý gì khi viết \"mình có khoản đó không\"?","opts":["He is trying to find a missing document.","He is wondering if there are enough funds.","He needs the contact information for a client.","He wants to confirm an account number."],"ans":"B","xp":"Ngay trước đó Camilla đề xuất hoàn khoảng 250 đô; Aruna đáp 'There's enough in our corporate bank account' → ông hỏi có đủ tiền không → (B)."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following advertisement.","passages":["<h3>Spring Sale at Rashid Gentlemen's Tailors</h3><p>Mr. J. Rashid, current CEO and son of Rashid Gentlemen's Tailors' founder, is pleased to announce that Master Tailor Joseph McPherson will be visiting the business and working on site until April 4. Having spent over 30 years in the Paris fashion district, Mr. McPherson is known worldwide for providing the perfect stitching and fit. <span class=\"pos\">[1]</span> So, this is a rare opportunity to purchase these one-of-a-kind goods.</p><p>To celebrate the event, Rashid Gentlemen's Tailors will be including a set of three complimentary dress shirts with any order of two custom-made suits. <span class=\"pos\">[2]</span> These will be hand fitted to the customer's specifications, just like all the suits we have produced for over six decades, and they will be available in a wide range of colors and styles. <span class=\"pos\">[3]</span> From April 4 onwards, Rashid Gentlemen's Tailors will be offering a full shirt-making service for the first time in our history, and these items will be available made-to-order or from a selection off-the-rack. <span class=\"pos\">[4]</span></p><p>Our overseas customers with measurements already on file will be able to take advantage of this opportunity as well. Simply log in and place an order through your online account at www.rashidgtailors.com using code MCP1022 in the appropriate section.</p>"],"vi":"Khuyến mãi mùa xuân tại tiệm may Rashid Gentlemen's Tailors\n\nÔng J. Rashid, giám đốc hiện tại và là con trai người sáng lập tiệm may Rashid, vui mừng thông báo thợ may bậc thầy Joseph McPherson sẽ đến làm việc tại tiệm đến ngày 4 tháng 4. Với hơn 30 năm ở khu thời trang Paris, ông McPherson nổi tiếng thế giới về đường may và độ vừa vặn hoàn hảo. Ông thường chỉ phục vụ người nổi tiếng và chính khách cấp cao. Vì vậy, đây là cơ hội hiếm có để mua những sản phẩm độc nhất này.\n\nĐể mừng sự kiện, tiệm sẽ tặng kèm bộ ba áo sơ mi khi đặt may hai bộ com-lê. Áo sẽ được may tay theo số đo của khách, giống như mọi bộ com-lê chúng tôi đã làm suốt hơn sáu thập kỷ, với nhiều màu sắc và kiểu dáng. Từ ngày 4 tháng 4, lần đầu tiên trong lịch sử, tiệm sẽ có dịch vụ may sơ mi trọn gói, khách có thể đặt may riêng hoặc chọn áo may sẵn.\n\nKhách hàng ở nước ngoài đã có số đo lưu tại tiệm cũng có thể tận dụng cơ hội này. Chỉ cần đăng nhập và đặt hàng qua tài khoản trực tuyến tại www.rashidgtailors.com, nhập mã MCP1022 vào ô tương ứng.","qs":[{"n":172,"q":"Who most likely is Mr. McPherson?","qvi":"Ông McPherson nhiều khả năng là ai?","opts":["A clothing distributor","A company's CEO","A tailoring intern","A guest professional"],"ans":"D","xp":"'Master Tailor Joseph McPherson will be visiting the business and working on site until April 4' → thợ may bậc thầy đến làm việc tạm thời → chuyên gia khách mời → (D). (B) CEO là ông Rashid."},{"n":173,"q":"What is NOT suggested about Rashid Gentlemen's Tailors?","qvi":"Điều gì KHÔNG được gợi ý về tiệm Rashid?","opts":["It is a family-owned business.","Its promotion will include free items.","It has been in business for over 60 years.","It currently makes formal shirts."],"ans":"D","xp":"(A) CEO là con của người sáng lập; (B) 'three complimentary dress shirts'; (C) 'over six decades'. Còn dịch vụ may sơ mi chỉ có 'From April 4 onwards... for the first time' → hiện tại chưa may sơ mi → (D)."},{"n":174,"q":"What is recommended for foreign buyers?","qvi":"Người mua ở nước ngoài được khuyên làm gì?","opts":["Booking appointments in advance","Ordering through a Web site","Sending their measurements via e-mail","Placing their suit orders early"],"ans":"B","xp":"'Our overseas customers... place an order through your online account at www.rashidgtailors.com' → (B). (C) số đo đã lưu sẵn."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"He usually caters exclusively to celebrities and high-level politicians.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Ông thường chỉ phục vụ người nổi tiếng và chính khách cấp cao.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"'He' là ông McPherson, được giới thiệu ở đoạn 1; câu sau vị trí [1] 'So, this is a rare opportunity' (cơ hội hiếm có) được giải thích bởi việc ông thường chỉ phục vụ người nổi tiếng → (A)."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following memo and schedule.","passages":["<div class=\"hdr\"><p><b>ATTN:</b> All Employees</p><p><b>SUBJECT:</b> Week of January 9 – 13</p><p><b>DATE:</b> Monday, January 2</p></div><p>The schedule for repainting our offices has been finalized. Attached is a schedule of the work that will take place. Please pull all furniture away from the walls to the center and cover them with given cloths on the evening of the day before your scheduled date so that the painters can work without obstructions. Although the paint should be dry after one day, it is best to plan on leaving your office for two days, except for the paintwork that will be done on Friday.</p><p>During the time your offices are being painted, please use Room 716, our main meeting room, as a temporary office. If you plan on using the meeting room next week, be sure to coordinate with whoever will be temporarily working there. Since it is the only room in our office with a microphone and speakers, holding a meeting there could be very distracting to anyone trying to use it as a temporary office space. Please contact management if you have any questions regarding this.</p>","<h3>Office Painting Schedule (January 9 – 13)</h3><table><tr><td>Monday, January 9</td><td>Room 704 (Michelle Cox)</td></tr><tr><td>Tuesday, January 10</td><td>Room 714 (Teddy Boyle)</td></tr><tr><td>Wednesday, January 11</td><td>Room 705 (Jessica Ramsey)</td></tr><tr><td>Thursday, January 12</td><td>Room 715 (John Hack)</td></tr><tr><td>Friday, January 13</td><td>Room 706 (James Holder &amp; Danielle Atchison)</td></tr></table>"],"vi":"Gửi: Toàn thể nhân viên | Chủ đề: Tuần 9–13 tháng 1 | Ngày: thứ Hai, 2 tháng 1\n\nLịch sơn lại các văn phòng đã được chốt. Kèm theo là lịch thi công. Vào tối hôm trước ngày được xếp lịch, vui lòng kéo toàn bộ đồ đạc ra khỏi tường, dồn vào giữa phòng và phủ bằng vải được phát để thợ sơn làm việc không bị vướng. Dù sơn sẽ khô sau một ngày, tốt nhất nên tính rời văn phòng trong hai ngày, trừ phần sơn làm vào thứ Sáu.\n\nTrong thời gian văn phòng được sơn, vui lòng dùng phòng 716, phòng họp chính, làm văn phòng tạm. Nếu định dùng phòng họp vào tuần sau, hãy sắp xếp với người đang tạm làm việc ở đó. Vì đây là phòng duy nhất có micro và loa, họp ở đó có thể làm phiền người đang dùng phòng làm văn phòng tạm. Vui lòng liên hệ ban quản lý nếu có thắc mắc.\n\nLịch sơn văn phòng (9–13/1): Thứ Hai 9/1 – phòng 704 (Michelle Cox); Thứ Ba 10/1 – phòng 714 (Teddy Boyle); Thứ Tư 11/1 – phòng 705 (Jessica Ramsey); Thứ Năm 12/1 – phòng 715 (John Hack); Thứ Sáu 13/1 – phòng 706 (James Holder và Danielle Atchison).","qs":[{"n":176,"q":"What is the main purpose of the memo?","qvi":"Mục đích chính của bản ghi nhớ là gì?","opts":["To give directions to the new office location","To announce a temporary workspace change","To gather feedback on the work environment","To specify what work needs to be done"],"ans":"B","xp":"Bản ghi nhớ báo lịch sơn văn phòng và yêu cầu nhân viên 'use Room 716... as a temporary office' trong lúc sơn → thông báo thay đổi chỗ làm tạm thời → (B)."},{"n":177,"q":"What are the employees asked to do for the scheduled work?","qvi":"Nhân viên được yêu cầu làm gì cho đợt thi công?","opts":["Package their personal belongings","Bring their own brushes","Cover their desks","Oversee some workers"],"ans":"C","xp":"'pull all furniture away from the walls to the center and cover them with given cloths' → phủ đồ đạc (bàn) → (C)."},{"n":178,"q":"What is mentioned about Room 716?","qvi":"Điều gì được nhắc đến về phòng 716?","opts":["It is the largest room in the building.","It will undergo renovations.","It is equipped with a sound system.","It can be reserved via the company's Web site."],"ans":"C","xp":"'it is the only room in our office with a microphone and speakers' → có hệ thống âm thanh → (C)."},{"n":179,"q":"When will Mr. Hack most likely move some furniture?","qvi":"Ông Hack nhiều khả năng sẽ dời đồ đạc khi nào?","opts":["On Monday, January 9","On Tuesday, January 10","On Wednesday, January 11","On Thursday, January 12"],"ans":"C","xp":"Lịch: phòng ông Hack sơn thứ Năm 12/1; bản ghi nhớ: dời đồ 'on the evening of the day before your scheduled date' → tối thứ Tư 11/1 → (C)."},{"n":180,"q":"What is implied about Ms. Atchison?","qvi":"Có thể suy ra điều gì về cô Atchison?","opts":["She has accepted a position at another company.","She shares an office with a coworker.","She will be moving to a new office.","She has recently been promoted to management."],"ans":"B","xp":"Lịch: 'Room 706 (James Holder & Danielle Atchison)' → hai người dùng chung một phòng → (B)."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following brochure and e-mail.","passages":["<h3>Byron Marketing</h3><p>www.byronmarketing.net</p><p>Brand recognition is the key to running a successful business. Let Byron Marketing help make your business known. Our services include:</p><p><b>Print</b> — The traditional option, this includes posters, flyers, and newspaper ads. Consult with one of our representatives for recommendations on the amount of copies that would be appropriate for your business.</p><p><b>Radio</b> — Since most people listen to the radio while in the car or office, this is the ideal choice if your target audience is working age. You can choose which stations to broadcast your company's commercial on.</p><p><b>Television</b> — This is a great option for reaching young audiences such as children. The combination of exciting audio and visuals can grab and keep their attention.</p><p><b>Internet</b> — Work with one of our graphic designers to decide the window dimensions that best suit your marketing needs. Then select the sites you want to advertise on.</p><p>We offer a free initial consultation during which you can select which services you would like us to provide. Follow-up consultations will be charged based on duration and number of services involved. All of our ad ideas will be presented for approval before final drafts are produced. E-mail us at custserv@byronmarketing.net or call us at 555-3189 to schedule a meeting.</p>","<div class=\"hdr\"><p><b>To:</b> Byron Marketing Customer Service &lt;custserv@byronmarketing.net&gt;</p><p><b>From:</b> Genevieve Wagner &lt;gwagner@wagner.net&gt;</p><p><b>Subject:</b> Ad Campaign</p><p><b>Date:</b> January 6</p></div><p>Hello, I'm the owner of Wagner Dolls. Just over a month ago I started my business, and I think that I need to run an ad campaign to promote it here. I think that kids in the area would really enjoy the handmade dolls that I sell. However, I need to find a way to get the word out about my products. Commercials produced by your company have made Lil' Truckers' Toy Shop famous, and I hope you can do the same for my business. I would like to meet with a representative of your company a week from today to discuss what you can offer. Thank you.</p><p>Sincerely,<br>Genevieve Wagner<br>Owner, Wagner Dolls</p>"],"vi":"Byron Marketing – www.byronmarketing.net\n\nNhận diện thương hiệu là chìa khóa để điều hành một doanh nghiệp thành công. Hãy để Byron Marketing giúp doanh nghiệp bạn được biết đến. Dịch vụ của chúng tôi gồm:\nIn ấn – Lựa chọn truyền thống: áp phích, tờ rơi, quảng cáo báo. Hãy hỏi nhân viên tư vấn để biết số lượng bản in phù hợp.\nRadio – Vì đa số người nghe radio khi ở trong xe hay văn phòng, đây là lựa chọn lý tưởng nếu khách hàng mục tiêu ở độ tuổi đi làm. Bạn có thể chọn đài phát quảng cáo.\nTruyền hình – Lựa chọn tuyệt vời để tiếp cận khán giả nhỏ tuổi như trẻ em. Âm thanh và hình ảnh sinh động sẽ thu hút và giữ sự chú ý của các em.\nInternet – Làm việc với nhà thiết kế đồ họa để chọn kích thước khung quảng cáo phù hợp, sau đó chọn các trang web muốn đăng.\nChúng tôi tư vấn miễn phí lần đầu, khi đó bạn chọn dịch vụ muốn dùng. Các lần tư vấn sau tính phí theo thời lượng và số dịch vụ. Mọi ý tưởng quảng cáo sẽ được trình bày để bạn duyệt trước khi làm bản hoàn chỉnh. E-mail custserv@byronmarketing.net hoặc gọi 555-3189 để hẹn gặp.\n\nNgười nhận: Bộ phận chăm sóc khách hàng Byron Marketing | Người gửi: Genevieve Wagner | Chủ đề: Chiến dịch quảng cáo | Ngày: 6/1\nXin chào, tôi là chủ cửa hàng Wagner Dolls. Tôi mới mở cửa hàng được hơn một tháng và nghĩ mình cần chạy chiến dịch quảng cáo ở đây. Tôi nghĩ trẻ em trong khu vực sẽ rất thích búp bê làm thủ công tôi bán. Nhưng tôi cần cách để mọi người biết đến sản phẩm. Các đoạn quảng cáo do công ty bạn sản xuất đã giúp cửa hàng đồ chơi Lil' Truckers nổi tiếng, và tôi mong các bạn cũng làm được vậy cho cửa hàng tôi. Tôi muốn gặp đại diện công ty bạn vào đúng một tuần nữa để bàn về dịch vụ. Cảm ơn.\nTrân trọng, Genevieve Wagner – Chủ cửa hàng Wagner Dolls","qs":[{"n":181,"q":"In the brochure, the word \"running\" in paragraph 1, line 1, is closest in meaning to","qvi":"Trong tờ giới thiệu, từ \"running\" ở đoạn 1, dòng 1 gần nghĩa nhất với","opts":["hurrying","moving","operating","broadcasting"],"ans":"C","xp":"'running a successful business' = điều hành doanh nghiệp → (C) operating."},{"n":182,"q":"What is NOT suggested about Byron Marketing?","qvi":"Điều gì KHÔNG được gợi ý về Byron Marketing?","opts":["It offers online consultation.","It shows its customers rough drafts.","It develops custom service plans.","It creates ads for multiple platforms."],"ans":"A","xp":"(B) 'ad ideas will be presented for approval before final drafts'; (C) khách tự chọn dịch vụ trong buổi tư vấn; (D) in ấn, radio, TV, Internet. Không nói có tư vấn trực tuyến (chỉ e-mail/gọi để hẹn gặp) → (A)."},{"n":183,"q":"What is indicated about Wagner Dolls?","qvi":"Điều gì được cho biết về Wagner Dolls?","opts":["It has done business with Byron Marketing before.","It specializes in imported goods.","It opened for business last year.","It creates custom designs on request."],"ans":"C","xp":"E-mail ngày 6/1: 'Just over a month ago I started my business' → mở cửa khoảng đầu tháng 12 năm trước → (C). (B) sai: búp bê làm thủ công."},{"n":184,"q":"Which option would Ms. Wagner be most interested in?","qvi":"Bà Wagner nhiều khả năng quan tâm lựa chọn nào nhất?","opts":["Print","Radio","Television","Internet"],"ans":"C","xp":"E-mail: 'kids in the area would really enjoy the handmade dolls' → khách mục tiêu là trẻ em; tờ giới thiệu: Television – 'a great option for reaching young audiences such as children' → (C)."},{"n":185,"q":"What can be inferred about Lil' Truckers' Toy Shop?","qvi":"Có thể suy ra điều gì về cửa hàng Lil' Truckers?","opts":["It sells toys that are made by hand.","It is the most successful toy store in the region.","It conducts most of its business online.","It has a contract with Byron Marketing."],"ans":"D","xp":"'Commercials produced by your company have made Lil' Truckers' Toy Shop famous' → cửa hàng này đã thuê Byron Marketing làm quảng cáo → (D)."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following advertisement, form, and e-mail.","passages":["<h3>Hometown Appliances - 451 Pine Street</h3><h4>One stop for all your household needs!</h4><p>Hometown Appliances has the area's largest selection of appliances for the kitchen, laundry room, and more. In celebration of our second anniversary, we are offering two special deals for customers throughout the month of February. Enter code NYT1030 on your order form to claim free delivery. You can also get 50% off installation fees using code NRL2997. Customers who sign up for our newsletter will also receive a free sample of EverShine household cleaner. To register, visit www.hometownappliances.com.</p>","<h3>Hometown Appliances Order Confirmation #860175</h3><table><tr><td>Name:</td><td>Johnathan Holt</td></tr><tr><td>Billing Address:</td><td>317 Terra Cotta Street, Ulen, MN 56585</td></tr><tr><td>Order Date:</td><td>February 3</td></tr><tr><td>Shipping Address:</td><td>Same as above</td></tr></table><table><tr><th>Items</th><th>Price</th></tr><tr><td>1) MaxHome coffee machine</td><td>$499.00</td></tr><tr><td>2) EasyClean vacuum cleaner</td><td>$120.00</td></tr><tr><td>3) Durham bread-making machine</td><td>$140.00</td></tr><tr><td>4) Kessler handheld food mixer</td><td>$69.99</td></tr><tr><td>Subtotal:</td><td>$828.99</td></tr><tr><td>Promo code (if applicable):</td><td>NYT1030</td></tr><tr><td>Total (includes delivery, installation, and taxes):</td><td>$878.73</td></tr><tr><td>Payment</td><td>Credit Card <b>*</b><b>*</b>**6767</td></tr><tr><td>Installation type</td><td>None</td></tr></table><p>Please note that all bank transfers must be marked with your reference number(s) in order for your order to be processed.</p><p><b>Replacement Guarantee</b> If an item ordered through Hometown Appliances is defective, we will replace it free of charge. Please contact our customer service team for information about our refund policy.</p>","<div class=\"hdr\"><p><b>To:</b> Hometown Appliances &lt;customerservice@hometownappliances.com&gt;</p><p><b>From:</b> Johnathan Holt &lt;j.holt@readymail.com&gt;</p><p><b>Date:</b> February 10</p><p><b>Subject:</b> Order #860175</p></div><p>To Whom It May Concern:</p><p>I would like to report an issue with the Durham product I ordered from you last week. The power cable is not properly attached to the base. I have not tried to plug it in, as it does not seem safe to do so. I am not sure if this falls under your Replacement Guarantee or if it is just subject to a refund. I would prefer the former, if possible, because I like the features of this particular device. This is a much better option for me than receiving a refund check in the mail. I have used Hometown Appliances in the past many times without any issues, so I'm sure this minor problem is no reflection on your usual level of quality.</p><p>Yours sincerely,<br>Johnathan Holt</p>"],"vi":"Hometown Appliances – 451 phố Pine. Một điểm đến cho mọi nhu cầu gia đình!\nHometown Appliances có nhiều đồ gia dụng nhất khu vực cho nhà bếp, phòng giặt và hơn thế nữa. Mừng kỷ niệm 2 năm thành lập, suốt tháng 2 chúng tôi có hai ưu đãi đặc biệt. Nhập mã NYT1030 vào đơn hàng để được giao hàng miễn phí. Bạn cũng được giảm 50% phí lắp đặt với mã NRL2997. Khách đăng ký nhận bản tin còn được tặng mẫu dùng thử nước tẩy rửa EverShine. Để đăng ký, hãy vào www.hometownappliances.com.\n\nXác nhận đơn hàng #860175 – Tên: Johnathan Holt | Địa chỉ thanh toán: 317 Terra Cotta Street, Ulen | Ngày đặt: 3/2 | Địa chỉ giao: như trên\nHàng: 1) Máy pha cà phê MaxHome 499 đô; 2) Máy hút bụi EasyClean 120 đô; 3) Máy làm bánh mì Durham 140 đô; 4) Máy đánh trứng cầm tay Kessler 69,99 đô. Tạm tính 828,99 đô. Mã khuyến mãi: NYT1030. Tổng (gồm giao hàng, lắp đặt, thuế): 878,73 đô. Thanh toán: thẻ tín dụng ****6767. Lắp đặt: không.\nLưu ý mọi khoản chuyển khoản phải ghi mã tham chiếu để đơn được xử lý.\nBảo đảm đổi hàng: nếu hàng đặt qua Hometown Appliances bị lỗi, chúng tôi sẽ đổi miễn phí. Vui lòng liên hệ bộ phận chăm sóc khách hàng để biết chính sách hoàn tiền.\n\nNgười nhận: Hometown Appliances | Người gửi: Johnathan Holt | Ngày: 10/2 | Chủ đề: Đơn hàng #860175\nKính gửi bộ phận liên quan, tôi muốn báo lỗi sản phẩm Durham tôi đặt tuần trước. Dây nguồn không được gắn chắc vào đế. Tôi chưa thử cắm điện vì thấy không an toàn. Tôi không rõ trường hợp này được đổi theo chính sách Bảo đảm đổi hàng hay chỉ được hoàn tiền. Tôi muốn được đổi hơn, vì tôi thích các tính năng của máy này. Như vậy tốt hơn nhiều so với nhận séc hoàn tiền qua bưu điện. Tôi đã mua ở Hometown Appliances nhiều lần mà không gặp vấn đề gì, nên tôi tin lỗi nhỏ này không phản ánh chất lượng thường ngày của cửa hàng.\nTrân trọng, Johnathan Holt","qs":[{"n":186,"q":"What is true about Hometown Appliances?","qvi":"Điều gì đúng về Hometown Appliances?","opts":["It has upgraded its Web site.","It has been open for over one year.","It has launched some new products.","It has moved to a new location."],"ans":"B","xp":"'In celebration of our second anniversary' → đã mở được 2 năm → hơn một năm → (B)."},{"n":187,"q":"How did Mr. Holt pay for his merchandise?","qvi":"Ông Holt thanh toán bằng cách nào?","opts":["By in-store credit","By bank transfer","By check","By credit card"],"ans":"D","xp":"Đơn hàng: 'Payment: Credit Card ************6767' → (D)."},{"n":188,"q":"What is implied about Mr. Holt's order?","qvi":"Có thể suy ra điều gì về đơn hàng của ông Holt?","opts":["It was delivered for free.","It had an incorrect price.","It had discounted installation.","It was not applicable to taxes."],"ans":"A","xp":"Đơn hàng dùng mã 'NYT1030'; quảng cáo: 'Enter code NYT1030... to claim free delivery' → được giao miễn phí → (A). (C) mã giảm lắp đặt là NRL2997, và đơn không lắp đặt."},{"n":189,"q":"According to Mr. Holt, which item has a problem?","qvi":"Theo ông Holt, món hàng nào bị lỗi?","opts":["The coffee machine","The vacuum cleaner","The bread-making machine","The handheld food mixer"],"ans":"C","xp":"E-mail: 'an issue with the Durham product'; đơn hàng: 'Durham bread-making machine' → (C)."},{"n":190,"q":"What does Mr. Holt want Hometown Appliances to do?","qvi":"Ông Holt muốn Hometown Appliances làm gì?","opts":["Credit his online account","Change his mailing address","Send a replacement product","Upgrade an existing order"],"ans":"C","xp":"'I am not sure if this falls under your Replacement Guarantee or... a refund. I would prefer the former' (cái trước = đổi hàng) → (C)."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mail, form, and article.","passages":["<div class=\"hdr\"><p><b>To:</b> Goodwin Solutions Employees</p><p><b>From:</b> Joanne Pruett</p><p><b>Date:</b> September 12</p><p><b>Subject:</b> Communication Workshops</p><p><b>Attachment:</b> sign-up request.docx</p></div><p>Goodwin Solutions will host a month-long communication workshop in October for full- and part-time employees who have worked for the company for at least twelve months. Due to the limited number of spots available, please only sign up if you can promise that you will not miss any parts of the workshop. It will be conducted every Thursday in October from 6 P.M. to 8 P.M., so it will not interfere with any work obligations assigned by your supervisor. A variety of topics will be covered by experienced lecturers.</p><p>If you are interested, please submit a completed copy of the attached request form to Rafael Vaughn at rvaughn@goodwinsol.com no later than September 19. Mr. Vaughn will evaluate the forms and choose the successful applicants on September 22.</p>","<h3>Communication Workshop Sign-Up Request</h3><table><tr><td>Name:</td><td>Tony Henning</td></tr><tr><td>Department:</td><td>Public Relations</td></tr><tr><td>Work e-mail:</td><td>t.henning@goodwinsol.com</td></tr><tr><td>Why are you interested in this workshop?</td><td>The main difficulty of my job is navigating the communication gap with my international clients, as the approach I should take varies depending on the culture. I would love to learn more about this.</td></tr><tr><td>Do you have any scheduling conflicts with the sessions?</td><td>No</td></tr></table>","<h3>Goodwin Solutions Company News</h3><h4>November Edition – Workshop Deemed Great Success</h4><p>In response to employee requests, Goodwin Solutions hosted a month-long workshop on communication. Various communication topics were covered over the course of four weeks, with presentations by senior staff members at Goodwin Solutions. \"I was honored to be a presenter for this project,\" said Kevin Terrell. \"Not only did it give me the opportunity to share my expertise with others, but also I became better acquainted with some of the staff members.\"</p><p>Participants in the program had overwhelmingly positive responses in the post-workshop feedback survey, with one hundred percent of them saying they would recommend it to others. \"I learned so much,\" said Tony Henning, who works in the PR department. \"I was particularly pleased with Kristie Fultz's talk, which helped me with the biggest challenge of my job, so I feel much more confident. In addition, I was able to network with other staff members and develop closer relationships with them.\"</p><p>Plans for a new workshop are already underway, and the details will be announced in the next newsletter.</p>"],"vi":"Người nhận: Nhân viên Goodwin Solutions | Người gửi: Joanne Pruett | Ngày: 12/9 | Chủ đề: Hội thảo giao tiếp | Đính kèm: phiếu đăng ký\nGoodwin Solutions sẽ tổ chức hội thảo giao tiếp kéo dài một tháng vào tháng 10 cho nhân viên toàn thời gian và bán thời gian đã làm việc cho công ty ít nhất 12 tháng. Do số chỗ có hạn, chỉ đăng ký nếu bạn cam kết không bỏ buổi nào. Hội thảo diễn ra mỗi thứ Năm của tháng 10, từ 6 đến 8 giờ tối, nên sẽ không ảnh hưởng công việc cấp trên giao. Nhiều chủ đề sẽ do các giảng viên giàu kinh nghiệm trình bày.\nNếu quan tâm, hãy gửi phiếu đăng ký đính kèm đã điền cho Rafael Vaughn (rvaughn@goodwinsol.com) chậm nhất ngày 19/9. Ông Vaughn sẽ xét phiếu và chọn người tham gia vào ngày 22/9.\n\nPhiếu đăng ký hội thảo giao tiếp – Tên: Tony Henning | Phòng: Quan hệ công chúng | E-mail: t.henning@goodwinsol.com\nVì sao bạn quan tâm? Khó khăn lớn nhất trong công việc của tôi là vượt qua khoảng cách giao tiếp với khách hàng quốc tế, vì cách tiếp cận phải thay đổi tùy theo văn hóa. Tôi rất muốn học thêm về điều này.\nBạn có bị trùng lịch với các buổi học không? Không.\n\nBản tin Goodwin Solutions – Số tháng 11: Hội thảo thành công rực rỡ\nĐáp ứng yêu cầu của nhân viên, Goodwin Solutions đã tổ chức hội thảo giao tiếp kéo dài một tháng. Nhiều chủ đề được trình bày trong bốn tuần bởi các nhân viên cấp cao của công ty. \"Tôi rất vinh dự được làm diễn giả,\" Kevin Terrell nói. \"Không chỉ được chia sẻ chuyên môn mà tôi còn thân thiết hơn với một số đồng nghiệp.\"\nNgười tham gia phản hồi rất tích cực trong khảo sát sau hội thảo, 100% nói sẽ giới thiệu cho người khác. \"Tôi học được rất nhiều,\" Tony Henning ở phòng Quan hệ công chúng nói. \"Tôi đặc biệt hài lòng với bài nói của Kristie Fultz, giúp tôi giải quyết khó khăn lớn nhất trong công việc, nên giờ tôi tự tin hơn nhiều. Tôi cũng kết nối được với các đồng nghiệp khác và thân thiết hơn với họ.\"\nKế hoạch cho hội thảo mới đang được chuẩn bị, chi tiết sẽ có trong bản tin sau.","qs":[{"n":191,"q":"What is true about the workshop?","qvi":"Điều gì đúng về hội thảo?","opts":["Participants must commit to attending all sessions.","Participants must get approval from their supervisor.","It is held at the company once per year.","It is intended for public relations employees only."],"ans":"A","xp":"E-mail: 'please only sign up if you can promise that you will not miss any parts of the workshop' → phải cam kết dự đủ → (A). (D) dành cho mọi nhân viên làm từ 12 tháng."},{"n":192,"q":"How will the participants in the program be determined?","qvi":"Người tham gia được chọn như thế nào?","opts":["By giving a presentation to a panel","By passing an online test","By attending a group interview","By being assessed by Mr. Vaughn"],"ans":"D","xp":"'Mr. Vaughn will evaluate the forms and choose the successful applicants' → (D)."},{"n":193,"q":"What is implied about Mr. Henning?","qvi":"Có thể suy ra điều gì về ông Henning?","opts":["He is being considered for a promotion.","He is currently employed as a part-time worker.","He has worked for Goodwin Solutions for more than a year.","He has recently lost some of his clients."],"ans":"C","xp":"Hội thảo chỉ dành cho người 'who have worked for the company for at least twelve months'; bài báo cho biết ông Henning đã tham gia → ông làm ở công ty ít nhất một năm → (C)."},{"n":194,"q":"What is suggested about Ms. Fultz?","qvi":"Có thể suy ra điều gì về bà Fultz?","opts":["She will create the schedule for the next workshop.","She covered some of Mr. Terrell's duties.","She gave a presentation on cultural differences.","She has a lot of experience in marketing methods."],"ans":"C","xp":"Bài báo: bài nói của bà Fultz 'helped me with the biggest challenge of my job'; phiếu đăng ký: khó khăn lớn nhất của ông Henning là giao tiếp với khách quốc tế 'varies depending on the culture' → bà nói về khác biệt văn hóa → (C)."},{"n":195,"q":"What advantage of the workshop do Mr. Terrell and Mr. Henning both mention?","qvi":"Ông Terrell và ông Henning đều nhắc đến lợi ích nào của hội thảo?","opts":["Building confidence","Getting to know coworkers","Improving sales figures","Sharing knowledge"],"ans":"B","xp":"Terrell: 'I became better acquainted with some of the staff members'; Henning: 'I was able to network with other staff members and develop closer relationships' → làm quen đồng nghiệp → (B). (A) chỉ Henning nói, (D) chỉ Terrell nói."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following article, letter, and voucher.","passages":["<h3>Tree-Planting Project to Commemorate Arbor Day</h3><p>by Carol Rollins</p><p>April 18—Trevino City will hold its first-ever event to celebrate Arbor Day, a holiday that recognizes the impact of trees on public health and the environment. Trees will be planted at four parks throughout the city, and these have been paid for through a combination of municipal funds and private donations. Volunteers are needed for clearing and preparing the planting area as well as planting and watering the new trees. Individuals who participate as volunteers will receive a voucher for a free tree to plant on their own property. Community groups are also encouraged to take part in the project, in which case the group leader will be given a voucher for ten trees to be shared with the group members. Planting will take place according to the following schedule:</p><ul><li>Monday, April 25: Maxwell Park, picnic area</li><li>Wednesday, April 27: Spring Park, near north parking lot</li><li>Friday, April 29: Avoca Park, along jogging path</li><li>Saturday, April 30: Cedar Park, near east playground</li></ul><p>For more information, visit www.trevinocity.gov/events.</p>","<p>Anastasia Whitcomb<br>207 Timbercrest Road<br>Omaha, NE 68102</p><p>Dear Ms. Whitcomb,</p><p>Thank you for your participation on the first day of our Arbor Day tree-planting project. Because of volunteers like you, we were able to realize our dream of improving the environment here in Trevino City by unleashing the benefits of health-giving trees. From fresh oxygen and shade to natural homes for birds and insects, trees truly are a gift that keeps on giving. Enclosed you will find a voucher that can be used at Eastside Nursery.</p><p>We would like to show as many pictures as possible from the event, so if you have any to share, please visit www.trevinocity.gov/events to upload them. We plan to make this event an annual tradition, and we hope you will consider participating in next year's event.</p><p>Warmest regards,<br>Lonzo Tocci</p>","<h3>Eastside Nursery Product Voucher</h3><p>This voucher entitles the holder to <b>10 complimentary tree saplings</b>.</p><p>The voucher is valid from May 1 and can be used for any of the above item types in stock. Not for use with other offers. Offer valid only at the Union Street branch, as the Victoria Lane location does not carry trees.</p><p>Issued to Anastasia Whitcomb by Lonzo Tocci (Trevino City)<br>Code: 3959</p>"],"vi":"Dự án trồng cây kỷ niệm Ngày Trồng cây – Carol Rollins\n18/4 — Thành phố Trevino sẽ tổ chức sự kiện đầu tiên mừng Ngày Trồng cây, ngày lễ ghi nhận tác động của cây xanh đối với sức khỏe cộng đồng và môi trường. Cây sẽ được trồng ở bốn công viên trong thành phố, kinh phí từ ngân sách thành phố và tiền quyên góp tư nhân. Cần tình nguyện viên dọn dẹp, chuẩn bị khu vực trồng, trồng và tưới cây mới. Mỗi cá nhân tình nguyện sẽ nhận phiếu tặng một cây để trồng tại nhà. Các nhóm cộng đồng cũng được khuyến khích tham gia; khi đó trưởng nhóm sẽ nhận phiếu tặng mười cây để chia cho thành viên. Lịch trồng cây: thứ Hai 25/4 – công viên Maxwell, khu dã ngoại; thứ Tư 27/4 – công viên Spring, gần bãi đỗ xe phía bắc; thứ Sáu 29/4 – công viên Avoca, dọc đường chạy bộ; thứ Bảy 30/4 – công viên Cedar, gần sân chơi phía đông. Thông tin thêm: www.trevinocity.gov/events.\n\nGửi bà Anastasia Whitcomb, 207 Timbercrest Road, Omaha\nCảm ơn bà đã tham gia ngày đầu tiên của dự án trồng cây. Nhờ những tình nguyện viên như bà, chúng tôi đã thực hiện được ước mơ cải thiện môi trường ở thành phố Trevino bằng những lợi ích của cây xanh. Từ không khí trong lành, bóng mát đến nơi ở tự nhiên cho chim và côn trùng, cây xanh thật sự là món quà cho đi mãi. Kèm theo thư là phiếu dùng tại vườn ươm Eastside.\nChúng tôi muốn đăng càng nhiều ảnh sự kiện càng tốt, nên nếu bà có ảnh, xin vào www.trevinocity.gov/events để tải lên. Chúng tôi dự định tổ chức sự kiện này hằng năm và mong bà sẽ tham gia vào năm sau.\nTrân trọng, Lonzo Tocci\n\nPhiếu tặng sản phẩm vườn ươm Eastside: người giữ phiếu được nhận 10 cây giống miễn phí. Phiếu có hiệu lực từ ngày 1/5, dùng cho các loại cây trên còn trong kho. Không dùng chung với ưu đãi khác. Chỉ áp dụng ở chi nhánh phố Union, vì chi nhánh Victoria Lane không bán cây. Cấp cho Anastasia Whitcomb bởi Lonzo Tocci (thành phố Trevino). Mã: 3959.","qs":[{"n":196,"q":"Where did Ms. Whitcomb volunteer for a project?","qvi":"Bà Whitcomb làm tình nguyện ở đâu?","opts":["At Avoca Park","At Cedar Park","At Maxwell Park","At Spring Park"],"ans":"C","xp":"Thư: 'Thank you for your participation on the first day'; bài báo: ngày đầu tiên thứ Hai 25/4 ở 'Maxwell Park' → (C)."},{"n":197,"q":"In the letter, the word \"realize\" in paragraph 1, line 2, is closest in meaning to","qvi":"Trong thư, từ \"realize\" ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["achieve","understand","notice","confirm"],"ans":"A","xp":"'realize our dream' = thực hiện được ước mơ → (A) achieve. (B) understand là nghĩa khác của realize ('nhận ra'), không hợp ở đây."},{"n":198,"q":"What does Mr. Tocci ask Ms. Whitcomb to do?","qvi":"Ông Tocci nhờ bà Whitcomb làm gì?","opts":["Reserve items at Eastside Nursery","E-mail her some pictures","Share her opinions","Post images on a Web site"],"ans":"D","xp":"'if you have any (pictures) to share, please visit www.trevinocity.gov/events to upload them' → đăng ảnh lên web → (D). (B) không phải gửi e-mail."},{"n":199,"q":"What is true about the voucher?","qvi":"Điều gì đúng về phiếu tặng?","opts":["It should be submitted online.","It cannot be combined with other offers.","Its expiration date is on May 1.","It can be used at two different branches."],"ans":"B","xp":"'Not for use with other offers' → (B). (C) ngày 1/5 là ngày bắt đầu hiệu lực; (D) chỉ dùng ở chi nhánh phố Union."},{"n":200,"q":"What is suggested about Ms. Whitcomb?","qvi":"Có thể suy ra điều gì về bà Whitcomb?","opts":["She lost her first voucher.","She was a group leader.","She plans to participate next year.","She placed a special order."],"ans":"B","xp":"Phiếu ghi '10 complimentary tree saplings'; bài báo: cá nhân nhận phiếu 1 cây, còn 'the group leader will be given a voucher for ten trees' → bà là trưởng nhóm → (B)."}]}]}};
